(4, 8, 'dental-implants-in-turkey-a-complete-guide-to-your-new-smile', '{\"en\":\"Dental Implants in Turkey: A Complete Guide to Your New Smile\",\"ar\":\"\\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0623\\u0633\\u0646\\u0627\\u0646 \\u0641\\u064a \\u062a\\u0631\\u0643\\u064a\\u0627: \\u062f\\u0644\\u064a\\u0644 \\u0634\\u0627\\u0645\\u0644 \\u0644\\u0627\\u0628\\u062a\\u0633\\u0627\\u0645\\u062a\\u0643 \\u0627\\u0644\\u062c\\u062f\\u064a\\u062f\\u0629\",\"fr\":\"Implants Dentaires en Turquie : Guide Complet pour votre Nouveau Sourire\",\"ru\":\"\\u0418\\u043c\\u043f\\u043b\\u0430\\u043d\\u0442\\u0430\\u0446\\u0438\\u044f \\u0437\\u0443\\u0431\\u043e\\u0432 \\u0432 \\u0422\\u0443\\u0440\\u0446\\u0438\\u0438: \\u041f\\u043e\\u043b\\u043d\\u043e\\u0435 \\u0440\\u0443\\u043a\\u043e\\u0432\\u043e\\u0434\\u0441\\u0442\\u0432\\u043e \\u043a \\u0432\\u0430\\u0448\\u0435\\u0439 \\u043d\\u043e\\u0432\\u043e\\u0439 \\u0443\\u043b\\u044b\\u0431\\u043a\\u0435\"}', '{\"en\":\"Dental Implants\",\"ar\":\"\\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0623\\u0633\\u0646\\u0627\\u0646\",\"fr\":\"Implant Dentaire\",\"ru\":\"\\u0418\\u043c\\u043f\\u043b\\u0430\\u043d\\u0442\\u0430\\u0446\\u0438\\u044f \\u0437\\u0443\\u0431\\u043e\\u0432\"}', 40, '{\"en\":\"Discover why Turkey is the top destination for dental implants, covering costs, technology, and the step-by-step procedure.\",\"ar\":\"\\u0627\\u0643\\u062a\\u0634\\u0641 \\u0644\\u0645\\u0627\\u0630\\u0627 \\u062a\\u0639\\u062a\\u0628\\u0631 \\u062a\\u0631\\u0643\\u064a\\u0627 \\u0627\\u0644\\u0648\\u062c\\u0647\\u0629 \\u0627\\u0644\\u0623\\u0648\\u0644\\u0649 \\u0644\\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0623\\u0633\\u0646\\u0627\\u0646\\u060c \\u0645\\u0639 \\u062a\\u063a\\u0637\\u064a\\u0629 \\u0627\\u0644\\u062a\\u0643\\u0627\\u0644\\u064a\\u0641 \\u0648\\u0627\\u0644\\u062a\\u0643\\u0646\\u0648\\u0644\\u0648\\u062c\\u064a\\u0627 \\u0648\\u0627\\u0644\\u0625\\u062c\\u0631\\u0627\\u0621\\u0627\\u062a \\u062e\\u0637\\u0648\\u0629 \\u0628\\u062e\\u0637\\u0648\\u0629.\",\"fr\":\"D\\u00e9couvrez pourquoi la Turquie est la destination n\\u00b01 pour les implants dentaires : co\\u00fbts, technologie et proc\\u00e9dure.\",\"ru\":\"\\u0423\\u0437\\u043d\\u0430\\u0439\\u0442\\u0435, \\u043f\\u043e\\u0447\\u0435\\u043c\\u0443 \\u0422\\u0443\\u0440\\u0446\\u0438\\u044f \\u044f\\u0432\\u043b\\u044f\\u0435\\u0442\\u0441\\u044f \\u043b\\u0443\\u0447\\u0448\\u0438\\u043c \\u043c\\u0435\\u0441\\u0442\\u043e\\u043c \\u0434\\u043b\\u044f \\u0438\\u043c\\u043f\\u043b\\u0430\\u043d\\u0442\\u0430\\u0446\\u0438\\u0438 \\u0437\\u0443\\u0431\\u043e\\u0432: \\u0441\\u0442\\u043e\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c, \\u0442\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u0438 \\u0438 \\u044d\\u0442\\u0430\\u043f\\u044b \\u043f\\u0440\\u043e\\u0446\\u0435\\u0434\\u0443\\u0440\\u044b.\"}', '{\"en\":null,\"ar\":null,\"fr\":null,\"ru\":null}', '{\"en\":\"Gravity Clinic\",\"ar\":\"Gravity Clinic\",\"fr\":\"Gravity Clinic\",\"ru\":\"Gravity Clinic\"}', '{\"en\":\"5 min\",\"ar\":\"5 min\",\"fr\":\"5 min\",\"ru\":\"5 min\"}', 1, '2026-04-07 16:59:28', '2026-04-19 14:01:21'),
(5, 3, 'fue-vs-dhi-which-hair-transplant-technique-is-right-for-you', '{\"en\":\"FUE vs. DHI: Which Hair Transplant Technique is Right for You?\",\"ar\":\"\\u062a\\u0642\\u0646\\u064a\\u0629 FUE \\u0645\\u0642\\u0627\\u0628\\u0644 DHI: \\u0623\\u064a \\u062a\\u0642\\u0646\\u064a\\u0629 \\u0644\\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0634\\u0639\\u0631 \\u0647\\u064a \\u0627\\u0644\\u0623\\u0646\\u0633\\u0628 \\u0644\\u0643\\u061f\",\"fr\":\"FUE vs DHI : Quelle technique de greffe de cheveux vous convient ?\",\"ru\":\"FUE \\u043f\\u0440\\u043e\\u0442\\u0438\\u0432 DHI: \\u041a\\u0430\\u043a\\u0430\\u044f \\u0442\\u0435\\u0445\\u043d\\u0438\\u043a\\u0430 \\u043f\\u0435\\u0440\\u0435\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0432\\u043e\\u043b\\u043e\\u0441 \\u043f\\u043e\\u0434\\u0445\\u043e\\u0434\\u0438\\u0442 \\u0438\\u043c\\u0435\\u043d\\u043d\\u043e \\u0432\\u0430\\u043c?\"}', '{\"en\":\"Male Hair Transplant\",\"ar\":\"\\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0634\\u0639\\u0631 \\u0644\\u0644\\u0631\\u062c\\u0627\\u0644\",\"fr\":\"Greffe Homme\",\"ru\":\"\\u041c\\u0443\\u0436\\u0447\\u0438\\u043d\\u044b\"}', 92, '{\"en\":\"We compare the two most popular hair transplant methods to help you decide which one offers the best results for your hair type.\",\"ar\":\"\\u0646\\u0642\\u0627\\u0631\\u0646 \\u0628\\u064a\\u0646 \\u0623\\u0634\\u0647\\u0631 \\u0637\\u0631\\u064a\\u0642\\u062a\\u064a\\u0646 \\u0644\\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0634\\u0639\\u0631 \\u0644\\u0645\\u0633\\u0627\\u0639\\u062f\\u062a\\u0643 \\u0641\\u064a \\u062a\\u062d\\u062f\\u064a\\u062f \\u0623\\u064a\\u0647\\u0645\\u0627 \\u064a\\u0642\\u062f\\u0645 \\u0623\\u0641\\u0636\\u0644 \\u0627\\u0644\\u0646\\u062a\\u0627\\u0626\\u062c \\u0644\\u0646\\u0648\\u0639 \\u0634\\u0639\\u0631\\u0643.\",\"fr\":\"Nous comparons les deux m\\u00e9thodes les plus populaires pour vous aider \\u00e0 choisir celle qui offre les meilleurs r\\u00e9sultats.\",\"ru\":\"\\u041c\\u044b \\u0441\\u0440\\u0430\\u0432\\u043d\\u0438\\u0432\\u0430\\u0435\\u043c \\u0434\\u0432\\u0430 \\u0441\\u0430\\u043c\\u044b\\u0445 \\u043f\\u043e\\u043f\\u0443\\u043b\\u044f\\u0440\\u043d\\u044b\\u0445 \\u043c\\u0435\\u0442\\u043e\\u0434\\u0430 \\u043f\\u0435\\u0440\\u0435\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0432\\u043e\\u043b\\u043e\\u0441, \\u0447\\u0442\\u043e\\u0431\\u044b \\u043f\\u043e\\u043c\\u043e\\u0447\\u044c \\u0432\\u0430\\u043c \\u0432\\u044b\\u0431\\u0440\\u0430\\u0442\\u044c \\u043b\\u0443\\u0447\\u0448\\u0438\\u0439 \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442 \\u0434\\u043b\\u044f \\u0432\\u0430\\u0448\\u0435\\u0433\\u043e \\u0442\\u0438\\u043f\\u0430 \\u0432\\u043e\\u043b\\u043e\\u0441.\"}', '{\"en\":\"\",\"ar\":\"\",\"fr\":\"\",\"ru\":\"\"}', '{\"en\":\"Gravity Clinic\",\"ar\":\"Gravity Clinic\",\"fr\":\"Gravity Clinic\",\"ru\":\"Gravity Clinic\"}', '{\"en\":\"6 min\",\"ar\":\"6 min\",\"fr\":\"6 min\",\"ru\":\"6 min\"}', 1, '2026-04-09 18:46:07', '2026-04-19 14:00:28'),
(6, 3, 'the-secret-to-a-perfect-hollywood-smile-veneers-and-beyond', '{\"en\":\"The Secret to a Perfect Hollywood Smile: Veneers and Beyond\",\"ar\":\"\\u0633\\u0631 \\u0627\\u0628\\u062a\\u0633\\u0627\\u0645\\u0629 \\u0647\\u0648\\u0644\\u064a\\u0648\\u062f \\u0627\\u0644\\u0645\\u062b\\u0627\\u0644\\u064a\\u0629: \\u0627\\u0644\\u0641\\u064a\\u0646\\u064a\\u0631 \\u0648\\u0645\\u0627 \\u0648\\u0631\\u0627\\u0621 \\u0630\\u0644\\u0643\",\"fr\":\"Le Secret d\'un Hollywood Smile Parfait : Facettes et plus encore\",\"ru\":\"\\u0421\\u0435\\u043a\\u0440\\u0435\\u0442 \\u0438\\u0434\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0433\\u043e\\u043b\\u043b\\u0438\\u0432\\u0443\\u0434\\u0441\\u043a\\u043e\\u0439 \\u0443\\u043b\\u044b\\u0431\\u043a\\u0438: \\u0412\\u0438\\u043d\\u0438\\u0440\\u044b \\u0438 \\u043d\\u0435 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e\"}', '{\"en\":\"Male Hair Transplant\",\"ar\":\"\\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0634\\u0639\\u0631 \\u0644\\u0644\\u0631\\u062c\\u0627\\u0644\",\"fr\":\"Greffe Homme\",\"ru\":\"\\u041c\\u0443\\u0436\\u0447\\u0438\\u043d\\u044b\"}', 93, '{\"en\":\"Learn how aesthetic dentistry can transform your appearance and boost your confidence with custom-made veneers.\",\"ar\":\"\\u062a\\u0639\\u0631\\u0641 \\u0639\\u0644\\u0649 \\u0643\\u064a\\u0641 \\u064a\\u0645\\u0643\\u0646 \\u0644\\u0637\\u0628 \\u0627\\u0644\\u0623\\u0633\\u0646\\u0627\\u0646 \\u0627\\u0644\\u062a\\u062c\\u0645\\u064a\\u0644\\u064a \\u0623\\u0646 \\u064a\\u063a\\u064a\\u0631 \\u0645\\u0638\\u0647\\u0631\\u0643 \\u0648\\u064a\\u0639\\u0632\\u0632 \\u062b\\u0642\\u062a\\u0643 \\u0628\\u0646\\u0641\\u0633\\u0643 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0642\\u0634\\u0648\\u0631 \\u0627\\u0644\\u0641\\u064a\\u0646\\u064a\\u0631 \\u0627\\u0644\\u0645\\u0635\\u0645\\u0645\\u0629 \\u062e\\u0635\\u064a\\u0635\\u0627\\u064b.\",\"fr\":\"Apprenez comment la dentisterie esth\\u00e9tique peut transformer votre apparence avec des facet