(2, 'Dr. Ahmed Yılmaz', '{\"en\":\"Dental Implant Specialist\",\"ar\":\"\\u0623\\u062e\\u0635\\u0627\\u0626\\u064a \\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0623\\u0633\\u0646\\u0627\\u0646\",\"fr\":\"Sp\\u00e9cialiste en implants dentaires\",\"ru\":\"\\u0421\\u043f\\u0435\\u0446\\u0438\\u0430\\u043b\\u0438\\u0441\\u0442 \\u043f\\u043e \\u0434\\u0435\\u043d\\u0442\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0438\\u043c\\u043f\\u043b\\u0430\\u043d\\u0442\\u0430\\u0446\\u0438\\u0438\"}', 36, 5.0, '12', '3500', '{\"en\":null,\"ar\":null,\"fr\":null,\"ru\":null}', '{\"en\":\"Dr. Ahmed Y\\u0131lmaz is a highly experienced dental implant specialist with over 12 years of expertise. He has successfully treated thousands of international patients using advanced techniques and modern technologies. He is known for delivering natural results with a focus on patient comfort and long-term success.\",\"ar\":\"\\u062f. \\u0623\\u062d\\u0645\\u062f \\u064a\\u0644\\u0645\\u0627\\u0632 \\u0647\\u0648 \\u0623\\u062e\\u0635\\u0627\\u0626\\u064a \\u0632\\u0631\\u0627\\u0639\\u0629 \\u0623\\u0633\\u0646\\u0627\\u0646 \\u0630\\u0648 \\u062e\\u0628\\u0631\\u0629 \\u0639\\u0627\\u0644\\u064a\\u0629 \\u062a\\u0632\\u064a\\u062f \\u0639\\u0646 12 \\u0639\\u0627\\u0645\\u0627\\u064b. \\u0646\\u062c\\u062d \\u0641\\u064a \\u0639\\u0644\\u0627\\u062c \\u0622\\u0644\\u0627\\u0641 \\u0627\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0627\\u0644\\u062f\\u0648\\u0644\\u064a\\u064a\\u0646 \\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u062a\\u0642\\u0646\\u064a\\u0627\\u062a \\u0645\\u062a\\u0637\\u0648\\u0631\\u0629 \\u0648\\u062a\\u0643\\u0646\\u0648\\u0644\\u0648\\u062c\\u064a\\u0627\\u062a \\u062d\\u062f\\u064a\\u062b\\u0629. \\u064a\\u0634\\u062a\\u0647\\u0631 \\u0628\\u062a\\u0642\\u062f\\u064a\\u0645 \\u0646\\u062a\\u0627\\u0626\\u062c \\u0637\\u0628\\u064a\\u0639\\u064a\\u0629 \\u0645\\u0639 \\u0627\\u0644\\u062a\\u0631\\u0643\\u064a\\u0632 \\u0639\\u0644\\u0649 \\u0631\\u0627\\u062d\\u0629 \\u0627\\u0644\\u0645\\u0631\\u064a\\u0636 \\u0648\\u0646\\u062c\\u0627\\u062d \\u0627\\u0644\\u0639\\u0644\\u0627\\u062c \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0645\\u062f\\u0649 \\u0627\\u0644\\u0637\\u0648\\u064a\\u0644.\",\"fr\":\"Le Dr Ahmed Y\\u0131lmaz est un sp\\u00e9cialiste des implants dentaires hautement exp\\u00e9riment\\u00e9, avec plus de 12 ans d\'expertise. Il a trait\\u00e9 avec succ\\u00e8s des milliers de patients internationaux en utilisant des techniques avanc\\u00e9es et des technologies modernes. Il est connu pour fournir des r\\u00e9sultats naturels en mettant l\'accent sur le confort du patient et le succ\\u00e8s \\u00e0 long terme.\",\"ru\":\"\\u0414\\u043e\\u043a\\u0442\\u043e\\u0440 \\u0410\\u0445\\u043c\\u0435\\u0434 \\u0419\\u044b\\u043b\\u043c\\u0430\\u0437 \\u2014 \\u0432\\u044b\\u0441\\u043e\\u043a\\u043e\\u043a\\u0432\\u0430\\u043b\\u0438\\u0444\\u0438\\u0446\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 \\u0441\\u043f\\u0435\\u0446\\u0438\\u0430\\u043b\\u0438\\u0441\\u0442 \\u043f\\u043e \\u0438\\u043c\\u043f\\u043b\\u0430\\u043d\\u0442\\u0430\\u0446\\u0438\\u0438 \\u0437\\u0443\\u0431\\u043e\\u0432 \\u0441 \\u0431\\u043e\\u043b\\u0435\\u0435 \\u0447\\u0435\\u043c 12-\\u043b\\u0435\\u0442\\u043d\\u0438\\u043c \\u043e\\u043f\\u044b\\u0442\\u043e\\u043c \\u0440\\u0430\\u0431\\u043e\\u0442\\u044b. \\u041e\\u043d \\u0443\\u0441\\u043f\\u0435\\u0448\\u043d\\u043e \\u0432\\u044b\\u043b\\u0435\\u0447\\u0438\\u043b \\u0442\\u044b\\u0441\\u044f\\u0447\\u0438 \\u0438\\u043d\\u043e\\u0441\\u0442\\u0440\\u0430\\u043d\\u043d\\u044b\\u0445 \\u043f\\u0430\\u0446\\u0438\\u0435\\u043d\\u0442\\u043e\\u0432, \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u0443\\u044f \\u043f\\u0435\\u0440\\u0435\\u0434\\u043e\\u0432\\u044b\\u0435 \\u043c\\u0435\\u0442\\u043e\\u0434\\u044b \\u0438 \\u0441\\u043e\\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u044b\\u0435 \\u0442\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u0438. \\u041e\\u043d \\u0438\\u0437\\u0432\\u0435\\u0441\\u0442\\u0435\\u043d \\u0434\\u043e\\u0441\\u0442\\u0438\\u0436\\u0435\\u043d\\u0438\\u0435\\u043c \\u0435\\u0441\\u0442\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0445 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u043e\\u0432, \\u0443\\u0434\\u0435\\u043b\\u044f\\u044f \\u043e\\u0441\\u043e\\u0431\\u043e\\u0435 \\u0432\\u043d\\u0438\\u043c\\u0430\\u043d\\u0438\\u0435 \\u043a\\u043e\\u043c\\u0444\\u043e\\u0440\\u0442\\u0443 \\u043f\\u0430\\u0446\\u0438\\u0435\\u043d\\u0442\\u043e\\u0432 \\u0438 \\u0434\\u043e\\u043b\\u0433\\u043e\\u0441\\u0440\\u043e\\u0447\\u043d\\u043e\\u043c\\u0443 \\u0443\\u0441\\u043f\\u0435\\u0445\\u0443 \\u043b\\u0435\\u0447\\u0435\\u043d\\u0438\\u044f.\"}', '{\"en\":null,\"ar\":null,\"fr\":null,\"ru\":null}', 1, '2026-04-05 21:57:00', '2026-04-08 20:55:20'),
(3, 'Dr. Elif Kaya', '{\"en\":\"Hair Transplant Specialist (FUE & DHI)\",\"ar\":\"\\u0623\\u062e\\u0635\\u0627\\u0626\\u064a\\u0629 \\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0634\\u0639\\u0631 (FUE & DHI)\",\"fr\":null,\"ru\":null}', 81, 5.0, '15', '5000', '{\"en\":null,\"ar\":null,\"fr\":null,\"ru\":null}', '{\"en\":\"r. Elif Kaya is a world-renowned hair restoration expert with 15 years of experience. Specializing in Micro-FUE and DHI techniques, she has transformed the lives of over 5,000 patients. She is internationally recognized for her artistic approach to natural hairline design and high-density implantation.\",\"ar\":\"\\u062f. \\u0625\\u064a\\u0644\\u064a\\u0641 \\u0643\\u0627\\u064a\\u0627 \\u0647\\u064a \\u062e\\u0628\\u064a\\u0631\\u0629 \\u0645\\u0634\\u0647\\u0648\\u0631\\u0629 \\u0639\\u0627\\u0644\\u0645\\u064a\\u0627\\u064b \\u0641\\u064a \\u0627\\u0633\\u062a\\u0639\\u0627\\u062f\\u0629 \\u0627\\u0644\\u0634\\u0639\\u0631 \\u0648\\u062a\\u062a\\u0645\\u062a\\u0639 \\u0628\\u062e\\u0628\\u0631\\u0629 15 \\u0639\\u0627\\u0645\\u0627\\u064b. \\u0645\\u062a\\u062e\\u0635\\u0635\\u0629 \\u0641\\u064a \\u062a\\u0642\\u0646\\u064a\\u0627\\u062a Micro-FUE \\u0648 DHI\\u060c \\u0648\\u0646\\u062c\\u062d\\u062a \\u0641\\u064a \\u062a\\u063a\\u064a\\u064a\\u0631 \\u062d\\u064a\\u0627\\u0629 \\u0623\\u0643\\u062b\\u0631 \\u0645\\u0646 5000 \\u0645\\u0631\\u064a\\u0636. \\u062a\\u062d\\u0638\\u0649 \\u0628\\u062a\\u0642\\u062f\\u064a\\u0631 \\u062f\\u0648\\u0644\\u064a \\u0644\\u0646\\u0647\\u062c\\u0647\\u0627 \\u0627\\u0644\\u0641\\u0646\\u064a \\u0641\\u064a \\u062a\\u0635\\u0645\\u064a\\u0645 \\u062e\\u0637 \\u0627\\u0644\\u0634\\u0639\\u0631 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0639\\u064a \\u0648\\u0627\\u0644\\u0632\\u0631\\u0627\\u0639\\u0629 \\u0639\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0643\\u062b\\u0627\\u0641\\u0629.\",\"fr\":\"Le Dr Elif Kaya est une experte en restauration capillaire de renomm\\u00e9e mondiale avec 15 ans d\'exp\\u00e9rience. Sp\\u00e9cialis\\u00e9e dans les techniques Micro-FUE et DHI, elle a transform\\u00e9 la vie de plus de 5 000 patients. Elle est internationalement reconnue pour son approche artistique de la conception naturelle de la ligne frontale et de l\'implantation haute densit\\u00e9.\",\"ru\":\"\\u0414\\u043e\\u043a\\u0442\\u043e\\u0440 \\u042d\\u043b\\u0438\\u0444 \\u041a\\u0430\\u0439\\u044f \\u2014 \\u0432\\u0441\\u0435\\u043c\\u0438\\u0440\\u043d\\u043e \\u0438\\u0437\\u0432\\u0435\\u0441\\u0442\\u043d\\u044b\\u0439 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0442 \\u043f\\u043e \\u0432\\u043e\\u0441\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u044e \\u0432\\u043e\\u043b\\u043e\\u0441 \\u0441 15-\\u043b\\u0435\\u0442\\u043d\\u0438\\u043c \\u043e\\u043f\\u044b\\u0442\\u043e\\u043c \\u0440\\u0430\\u0431\\u043e\\u0442\\u044b. \\u0421\\u043f\\u0435\\u0446\\u0438\\u0430\\u043b\\u0438\\u0437\\u0438\\u0440\\u0443\\u044f\\u0441\\u044c \\u043d\\u0430 \\u043c\\u0435\\u0442\\u043e\\u0434\\u0430\\u0445 Micro-FUE \\u0438 DHI, \\u043e\\u043d\\u0430 \\u0438\\u0437\\u043c\\u0435\\u043d\\u0438\\u043b\\u0430 \\u0436\\u0438\\u0437\\u043d\\u044c \\u0431\\u043e\\u043b\\u0435\\u0435 \\u0447\\u0435\\u043c 5000 \\u043f\\u0430\\u0446\\u0438\\u0435\\u043d\\u0442\\u043e\\u0432. \\u041e\\u043d\\u0430 \\u043f\\u043e\\u043b\\u0443\\u0447\\u0438\\u043b\\u0430 \\u043c\\u0435\\u0436\\u0434\\u0443\\u043d\\u0430\\u0440\\u043e\\u0434\\u043d\\u043e\\u0435 \\u043f\\u0440\\u0438\\u0437\\u043d\\u0430\\u043d\\u0438\\u0435 \\u0431\\u043b\\u0430\\u0433\\u043e\\u0434\\u0430\\u0440\\u044f \\u0441\\u0432\\u043e\\u0435\\u043c\\u0443 \\u0445\\u0443\\u0434\\u043e\\u0436\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e\\u043c\\u0443 \\u043f\\u043e\\u0434\\u0445\\u043e\\u0434\\u0443 \\u043a \\u0441\\u043e\\u0437\\u0434\\u0430\\u043d\\u0438\\u044e \\u0435\\u0441\\u0442\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e\\u0439 \\u043b\\u0438\\u043d\\u0438\\u0438 \\u0440\\u043e\\u0441\\u0442\\u0430 \\u0432\\u043e\\u043b\\u043e\\u0441 \\u0438 \\u0438\\u043c\\u043f\\u043b\\u0430\\u043d\\u0442\\u0430\\u0446\\u0438\\u0438 \\u0432\\u044b\\u0441\\u043e\\u043a\\u043e\\u0439 \\u043f\\u043b\\u043e\\u0442\\u043d\\u043e\\u0441\\u0442\\u0438.\"}', '{\"en\":null,\"ar\":null,\"fr\":null,\"ru\":null}', 1, '2026-04-08 20:57:44', '2026-04-08 21:07:42'),
(4, 'Dr. Murat Aydın', '{\"en\":\"Aesthetic Dentist & Smile Design Expert\",\"ar\":\"\\u0623\\u062e\\u0635\\u0627\\u0626\\u064a \\u062a\\u062c\\u0645\\u064a\\u0644 \\u0627\\u0644\\u0623\\u0633\\u0646\\u0627\\u0646 \\u0648\\u062a\\u0635\\u0645\\u064a\\u0645 \\u0627\\u0644\\u0627\\u0628\\u062a\\u0633\\u0627\\u0645\\u0629\",\"fr\":\"Dentiste Esth\\u00e9tique & Expert en Design du Sourire\",\"ru\":\"\\u0421\\u0442\\u043e\\u043c\\u0430\\u0442\\u043e\\u043b\\u043e\\u0433-\\u044d\\u0441\\u0442\\u0435\\u0442\\u0438\\u0441\\u0442 \\u0438 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0442 \\u043f\\u043e \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0443 \\u0443\\u043b\\u044b\\u0431\\u043a\\u0438\"}', 79, 5.0, '10', '2800', '{\"en\":null,\"ar\":null,\"fr\":null,\"ru\":null}', '{\"en\":\"Dr. Murat Ayd\\u0131n is a premier aesthetic dentist specializing in Hollywood Smile makeovers and advanced porcelain veneers. With a decade of experience, he combines digital dentistry with an artistic eye to create symmetrical, bright, and natural-looking smiles. He is dedicated to providing painless treatments and transformative aesthetic results.\",\"ar\":\"\\u062f. \\u0645\\u0631\\u0627\\u062f \\u0623\\u064a\\u062f\\u064a\\u0646 \\u0647\\u0648 \\u0637\\u0628\\u064a\\u0628 \\u0623\\u0633\\u0646\\u0627\\u0646 \\u062a\\u062c\\u0645\\u064a\\u0644\\u064a \\u0628\\u0627\\u0631\\u0632 \\u0645\\u062a\\u062e\\u0635\\u0635 \\u0641\\u064a \\u062a\\u062d\\u0648\\u064a\\u0644 \\u0627\\u0644\\u0627\\u0628\\u062a\\u0633\\u0627\\u0645\\u0629 (\\u0627\\u0628\\u062a\\u0633\\u0627\\u0645\\u0629 \\u0647\\u0648\\u0644\\u064a\\u0648\\u062f) \\u0648\\u0642\\u0634\\u0648\\u0631 \\u0627\\u0644\\u0628\\u0648\\u0631\\u0633\\u0644\\u064a\\u0646 \\u0627\\u0644\\u0645\\u062a\\u0642\\u062f\\u0645\\u0629. \\u0645\\u0639 \\u0639\\u0642\\u062f \\u0645\\u0646 \\u0627\\u0644\\u062e\\u0628\\u0631\\u0629\\u060c \\u064a\\u062c\\u0645\\u0639 \\u0628\\u064a\\u0646 \\u0637\\u0628 \\u0627\\u0644\\u0623\\u0633\\u0646\\u0627\\u0646 \\u0627\\u0644\\u0631\\u0642\\u0645\\u064a \\u0648\\u0627\\u0644\\u0646\\u0638\\u0631\\u0629 \\u0627\\u0644\\u0641\\u0646\\u064a\\u0629 \\u0644\\u0625\\u0646\\u0634\\u0627\\u0621 \\u0627\\u0628\\u062a\\u0633\\u0627\\u0645\\u0627\\u062a \\u0645\\u062a\\u0646\\u0627\\u0638\\u0631\\u0629 \\u0648\\u0645\\u0634\\u0631\\u0642\\u0629 \\u0648\\u0637\\u0628\\u064a\\u0639\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0638\\u0647\\u0631. \\u064a\\u0643\\u0631\\u0633 \\u062c\\u0647\\u0648\\u062f\\u0647 \\u0644\\u062a\\u0642\\u062f\\u064a\\u0645 \\u0639\\u0644\\u0627\\u062c\\u0627\\u062a \\u063a\\u064a\\u0631 \\u0645\\u0624\\u0644\\u0645\\u0629 \\u0648\\u0646\\u062a\\u0627\\u0626\\u062c \\u062a\\u062c\\u0645\\u064a\\u0644\\u064a\\u0629 \\u0645\\u0630\\u0647\\u0644\\u0629.\",\"fr\":\"Le Dr Murat Ayd\\u0131n est un dentiste esth\\u00e9tique de premier plan, sp\\u00e9cialis\\u00e9 dans le Hollywood Smile et les facettes en porcelaine avanc\\u00e9es. Avec dix ans d\'exp\\u00e9rience, il combine la dentisterie num\\u00e9rique avec un \\u0153il artistique pour cr\\u00e9er des sourires sym\\u00e9triques, \\u00e9clatants et naturels. Il se consacre \\u00e0 fournir des traitements sans douleur et des r\\u00e9sultats esth\\u00e9tiques transformateurs.\",\"ru\":\"\\u0414\\u043e\\u043a\\u0442\\u043e\\u0440 \\u041c\\u0443\\u0440\\u0430\\u0442 \\u0410\\u0439\\u0434\\u044b\\u043d \\u2014 \\u0432\\u0435\\u0434\\u0443\\u0449\\u0438\\u0439 \\u0441\\u0442\\u043e\\u043c\\u0430\\u0442\\u043e\\u043b\\u043e\\u0433-\\u044d\\u0441\\u0442\\u0435\\u0442\\u0438\\u0441\\u0442, \\u0441\\u043f\\u0435\\u0446\\u0438\\u0430\\u043b\\u0438\\u0437\\u0438\\u0440\\u0443\\u044e\\u0449\\u0438\\u0439\\u0441\\u044f \\u043d\\u0430 \\u00ab\\u0433\\u043e\\u043b\\u043b\\u0438\\u0432\\u0443\\u0434\\u0441\\u043a\\u043e\\u0439 \\u0443\\u043b\\u044b\\u0431\\u043a\\u0435\\u00bb \\u0438 \\u0441\\u043e\\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u044b\\u0445 \\u0444\\u0430\\u0440\\u0444\\u043e\\u0440\\u043e\\u0432\\u044b\\u0445 \\u0432\\u0438\\u043d\\u0438\\u0440\\u0430\\u0445. \\u0418\\u043c\\u0435\\u044f \\u0434\\u0435\\u0441\\u044f\\u0442\\u0438\\u043b\\u0435\\u0442\\u043d\\u0438\\u0439 \\u043e\\u043f\\u044b\\u0442 \\u0440\\u0430\\u0431\\u043e\\u0442\\u044b, \\u043e\\u043d \\u0441\\u043e\\u0447\\u0435\\u0442\\u0430\\u0435\\u0442 \\u0446\\u0438\\u0444\\u0440\\u043e\\u0432\\u0443\\u044e \\u0441\\u0442\\u043e\\u043c\\u0430\\u0442\\u043e\\u043b\\u043e\\u0433\\u0438\\u044e \\u0441 \\u0445\\u0443\\u0434\\u043e\\u0436\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u043c \\u043f\\u043e\\u0434\\u0445\\u043e\\u0434\\u043e\\u043c \\u0434\\u043b\\u044f \\u0441\\u043e\\u0437\\u0434\\u0430\\u043d\\u0438\\u044f \\u0441\\u0438\\u043c\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u044b\\u0445, \\u044f\\u0440\\u043a\\u0438\\u0445 \\u0438 \\u0435\\u0441\\u0442\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0445 \\u0443\\u043b\\u044b\\u0431\\u043e\\u043a. \\u041e\\u043d \\u0441\\u0442\\u0440\\u0435\\u043c\\u0438\\u0442\\u0441\\u044f \\u043e\\u0431\\u0435\\u0441\\u043f\\u0435\\u0447\\u0438\\u0442\\u044c \\u0431\\u0435\\u0437\\u0431\\u043e\\u043b\\u0435\\u0437\\u043d\\u0435\\u043d\\u043d\\u043e\\u0435 \\u043b\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435 \\u0438 \\u0432\\u043f\\u0435\\u0447\\u0430\\u0442\\u043b\\u044f\\u044e\\u0449\\u0438\\u0435 \\u044d\\u0441\\u0442\\u0435\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u044b.\"}', '{\"en\":null,\"ar\":null,\"fr\":null,\"ru\":null}', 1, '2026-04-08 21:00:00', '2026-04-08 21:05:44'),
(5, 'Dr. Selin Demir', '{\"en\":\"Facial Aesthetic & Plastic Surgeon\",\"ar\":\"\\u062c\\u0631\\u0627\\u062d\\u0629 \\u062a\\u062c\\u0645\\u064a\\u0644 \\u0627\\u0644\\u0648\\u062c\\u0647 \\u0648\\u0627\\u0644\\u062a\\u0631\\u0645\\u064a\\u0645\",\"fr\":\"Chirurgienne Esth\\u00e9tique et Plastique Faciale\",\"ru\":\"\\u041f\\u043b\\u0430\\u0441\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0438 \\u0447\\u0435\\u043b\\u044e\\u0441\\u0442\\u043d\\u043e-\\u043b\\u0438\\u0446\\u0435\\u0432\\u043e\\u0439 \\u0445\\u0438\\u0440\\u0443\\u0440\\u0433\"}', 80, 5.0, '8', '1500', '{\"en\":null,\"ar\":null,\"fr\":null,\"ru\":null}', '{\"en\":\"Dr. Selin Demir is a highly skilled plastic surgeon specializing in facial aesthetics and non-surgical rejuvenations. With 8 years of clinical excellence, she focuses on achieving facial harmony and subtle, elegant enhancements. Her philosophy centers on patient safety and using the latest medical innovations to deliver personalized aesthetic transformations.\",\"ar\":\"\\u062f. \\u0633\\u064a\\u0644\\u064a\\u0646 \\u062f\\u0645\\u064a\\u0631 \\u0647\\u064a \\u062c\\u0631\\u0627\\u062d\\u0629 \\u062a\\u062c\\u0645\\u064a\\u0644 \\u0645\\u0627\\u0647\\u0631\\u0629 \\u0644\\u0644\\u063a\\u0627\\u064a\\u0629 \\u0645\\u062a\\u062e\\u0635\\u0635\\u0629 \\u0641\\u064a \\u062a\\u062c\\u0645\\u064a\\u0644 \\u0627\\u0644\\u0648\\u062c\\u0647 \\u0648\\u062a\\u062c\\u062f\\u064a\\u062f \\u0627\\u0644\\u0634\\u0628\\u0627\\u0628 \\u063a\\u064a\\u0631 \\u0627\\u0644\\u062c\\u0631\\u0627\\u062d\\u064a. \\u0645\\u0639 8 \\u0633\\u0646\\u0648\\u0627\\u062a \\u0645\\u0646 \\u0627\\u0644\\u062a\\u0645\\u064a\\u0632 \\u0627\\u0644\\u0633\\u0631\\u064a\\u0631\\u064a\\u060c \\u062a\\u0631\\u0643\\u0632 \\u0639\\u0644\\u0649 \\u062a\\u062d\\u0642\\u064a\\u0642 \\u062a\\u0646\\u0627\\u0633\\u0642 \\u0627\\u0644\\u0648\\u062c\\u0647 \\u0648\\u062a\\u062d\\u0633\\u064a\\u0646\\u0627\\u062a \\u0623\\u0646\\u064a\\u0642\\u0629 \\u0648\\u0637\\u0628\\u064a\\u0639\\u064a\\u0629. \\u062a\\u0631\\u062a\\u0643\\u0632 \\u0641\\u0644\\u0633\\u0641\\u062a\\u0647\\u0627 \\u0639\\u0644\\u0649 \\u0633\\u0644\\u0627\\u0645\\u0629 \\u0627\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0648\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u0623\\u062d\\u062f\\u062b \\u0627\\u0644\\u0627\\u0628\\u062a\\u0643\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0644\\u062a\\u0642\\u062f\\u064a\\u0645 \\u062a\\u062d\\u0648\\u0644\\u0627\\u062a \\u062a\\u062c\\u0645\\u064a\\u0644\\u064a\\u0629 \\u0645\\u062e\\u0635\\u0635\\u0629.\",\"fr\":\"Le Dr Selin Demir est une chirurgienne plasticienne hautement qualifi\\u00e9e, sp\\u00e9cialis\\u00e9e dans l\'esth\\u00e9tique du visage et le rajeunissement non chirurgical. Avec 8 ans d\'excellence clinique, elle se concentre sur l\'harmonie faciale et les am\\u00e9liorations subtiles et \\u00e9l\\u00e9gantes. Sa philosophie est centr\\u00e9e sur la s\\u00e9curit\\u00e9 des patients et l\'utilisation des derni\\u00e8res innovations m\\u00e9dicales pour offrir des transformations esth\\u00e9tiques personnalis\\u00e9es.\",\"ru\":\"\\u0414\\u043e\\u043a\\u0442\\u043e\\u0440 \\u0421\\u0435\\u043b\\u0438\\u043d \\u0414\\u0435\\u043c\\u0438\\u0440 \\u2014 \\u0432\\u044b\\u0441\\u043e\\u043a\\u043e\\u043a\\u0432\\u0430\\u043b\\u0438\\u0444\\u0438\\u0446\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 \\u043f\\u043b\\u0430\\u0441\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0445\\u0438\\u0440\\u0443\\u0440\\u0433, \\u0441\\u043f\\u0435\\u0446\\u0438\\u0430\\u043b\\u0438\\u0437\\u0438\\u0440\\u0443\\u044e\\u0449\\u0438\\u0439\\u0441\\u044f \\u043d\\u0430 \\u044d\\u0441\\u0442\\u0435\\u0442\\u0438\\u043a\\u0435 \\u043b\\u0438\\u0446\\u0430 \\u0438 \\u0431\\u0435\\u0437\\u043e\\u043f\\u0435\\u0440\\u0430\\u0446\\u0438\\u043e\\u043d\\u043d\\u043e\\u043c \\u043e\\u043c\\u043e\\u043b\\u043e\\u0436\\u0435\\u043d\\u0438\\u0438. \\u0418\\u043c\\u0435\\u044f 8-\\u043b\\u0435\\u0442\\u043d\\u0438\\u0439 \\u043e\\u043f\\u044b\\u0442 \\u043a\\u043b\\u0438\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0439 \\u0440\\u0430\\u0431\\u043e\\u0442\\u044b, \\u043e\\u043d\\u0430 \\u0443\\u0434\\u0435\\u043b\\u044f\\u0435\\u0442 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u043e\\u0435 \\u0432\\u043d\\u0438\\u043c\\u0430\\u043d\\u0438\\u0435 \\u0433\\u0430\\u0440\\u043c\\u043e\\u043d\\u0438\\u0438 \\u043b\\u0438\\u0446\\u0430 \\u0438 \\u0434\\u0435\\u043b\\u0438\\u043a\\u0430\\u0442\\u043d\\u044b\\u043c, \\u044d\\u043b\\u0435\\u0433\\u0430\\u043d\\u0442\\u043d\\u044b\\u043c \\u0438\\u0437\\u043c\\u0435\\u043d\\u0435\\u043d\\u0438\\u044f\\u043c. \\u0415\\u0451 \\u0444\\u0438\\u043b\\u043e\\u0441\\u043e\\u0444\\u0438\\u044f \\u043e\\u0441\\u043d\\u043e\\u0432\\u0430\\u043d\\u0430 \\u043d\\u0430 \\u0431\\u0435\\u0437\\u043e\\u043f\\u0430\\u0441\\u043d\\u043e\\u0441\\u0442\\u0438 \\u043f\\u0430\\u0446\\u0438\\u0435\\u043d\\u0442\\u043e\\u0432 \\u0438 \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u0438 \\u043d\\u043e\\u0432\\u0435\\u0439\\u0448\\u0438\\u0445 \\u043c\\u0435\\u0434\\u0438\\u0446\\u0438\\u043d\\u0441\\u043a\\u0438\\u0445 \\u0438\\u043d\\u043d\\u043e\\u0432\\u0430\\u0446\\u0438\\u0439 \\u0434\\u043b\\u044f \\u0434\\u043e\\u0441\\u0442\\u0438\\u0436\\u0435\\u043d\\u0438\\u044f \\u0438\\u043d\\u0434\\u0438\\u0432\\u0438\\u0434\\u0443\\u0430\\u043b\\u044c\\u043d\\u044b\\u0445 \\u044d\\u0441\\u0442\\u0435\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0445 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u043e\\u0432.\"}', '{\"en\":null,\"ar\":null,\"fr\":null,\"ru\":null}', 1, '2026-04-08 21:02:00', '2026-04-08 21:06:24');

