(3, '{\"en\":\"How long does a dental implant last?\",\"ar\":\"\\u0643\\u0645 \\u062a\\u062f\\u0648\\u0645 \\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0623\\u0633\\u0646\\u0627\\u0646\\u061f\",\"fr\":\"Combien de temps dure un implant dentaire ?\",\"ru\":\"\\u041a\\u0430\\u043a \\u0434\\u043e\\u043b\\u0433\\u043e \\u0441\\u043b\\u0443\\u0436\\u0438\\u0442 \\u0437\\u0443\\u0431\\u043d\\u043e\\u0439 \\u0438\\u043c\\u043f\\u043b\\u0430\\u043d\\u0442\\u0430\\u0442?\"}', '{\"en\":\"Dental implants can last for many years, often a lifetime, with proper care.\",\"ar\":\"\\u064a\\u0645\\u0643\\u0646 \\u0623\\u0646 \\u062a\\u062f\\u0648\\u0645 \\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0623\\u0633\\u0646\\u0627\\u0646 \\u0644\\u0633\\u0646\\u0648\\u0627\\u062a \\u0639\\u062f\\u064a\\u062f\\u0629\\u060c \\u0648\\u063a\\u0627\\u0644\\u0628\\u0627\\u064b \\u0645\\u0627 \\u062a\\u062f\\u0648\\u0645 \\u0645\\u062f\\u0649 \\u0627\\u0644\\u062d\\u064a\\u0627\\u0629 \\u0645\\u0639 \\u0627\\u0644\\u0639\\u0646\\u0627\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0646\\u0627\\u0633\\u0628\\u0629 \\u0648\\u0627\\u0644\\u0641\\u062d\\u0648\\u0635\\u0627\\u062a \\u0627\\u0644\\u062f\\u0648\\u0631\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0646\\u062a\\u0638\\u0645\\u0629.\",\"fr\":\"Les implants dentaires peuvent durer de nombreuses ann\\u00e9es, souvent toute une vie, avec des soins appropri\\u00e9s et des examens dentaires r\\u00e9guliers.\",\"ru\":\"\\u0417\\u0443\\u0431\\u043d\\u044b\\u0435 \\u0438\\u043c\\u043f\\u043b\\u0430\\u043d\\u0442\\u0430\\u0442\\u044b \\u043c\\u043e\\u0433\\u0443\\u0442 \\u0441\\u043b\\u0443\\u0436\\u0438\\u0442\\u044c \\u0434\\u043e\\u043b\\u0433\\u0438\\u0435 \\u0433\\u043e\\u0434\\u044b, \\u0447\\u0430\\u0441\\u0442\\u043e \\u0432\\u0441\\u044e \\u0436\\u0438\\u0437\\u043d\\u044c, \\u043f\\u0440\\u0438 \\u043d\\u0430\\u0434\\u043b\\u0435\\u0436\\u0430\\u0449\\u0435\\u043c \\u0443\\u0445\\u043e\\u0434\\u0435 \\u0438 \\u0440\\u0435\\u0433\\u0443\\u043b\\u044f\\u0440\\u043d\\u044b\\u0445 \\u043e\\u0441\\u043c\\u043e\\u0442\\u0440\\u0430\\u0445 \\u0443 \\u0441\\u0442\\u043e\\u043c\\u0430\\u0442\\u043e\\u043b\\u043e\\u0433\\u0430.\"}', 1, '2026-04-07 17:01:39', '2026-04-09 19:14:27'),
(4, '{\"en\":\"Is the dental implant procedure painful\",\"ar\":\"\\u0647\\u0644 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0623\\u0633\\u0646\\u0627\\u0646 \\u0645\\u0624\\u0644\\u0645\\u0629\\u061f\",\"fr\":\"La pose d\'un implant dentaire est-elle douloureuse ?\",\"ru\":\"\\u0411\\u043e\\u043b\\u0435\\u0437\\u043d\\u0435\\u043d\\u043d\\u0430 \\u043b\\u0438 \\u043f\\u0440\\u043e\\u0446\\u0435\\u0434\\u0443\\u0440\\u0430 \\u0438\\u043c\\u043f\\u043b\\u0430\\u043d\\u0442\\u0430\\u0446\\u0438\\u0438 \\u0437\\u0443\\u0431\\u043e\\u0432?\"}', '{\"en\":\"The procedure is performed under local anesthesia, so patients feel minimal discomfort\",\"ar\":\"\\u064a\\u062a\\u0645 \\u0625\\u062c\\u0631\\u0627\\u0621 \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629 \\u062a\\u062d\\u062a \\u0627\\u0644\\u062a\\u062e\\u062f\\u064a\\u0631 \\u0627\\u0644\\u0645\\u0648\\u0636\\u0639\\u064a\\u060c \\u0644\\u0630\\u0644\\u0643 \\u064a\\u0634\\u0639\\u0631 \\u0627\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0628\\u0623\\u0642\\u0644 \\u0642\\u062f\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0627\\u0646\\u0632\\u0639\\u0627\\u062c. \\u064a\\u0634\\u064a\\u0631 \\u0645\\u0639\\u0638\\u0645 \\u0627\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0625\\u0644\\u0649 \\u0634\\u0639\\u0648\\u0631\\u0647\\u0645 \\u0628\\u0623\\u0644\\u0645 \\u0623\\u0642\\u0644 \\u0628\\u0643\\u062b\\u064a\\u0631 \\u0645\\u0645\\u0627 \\u0643\\u0627\\u0646\\u0648\\u0627 \\u064a\\u062a\\u0648\\u0642\\u0639\\u0648\\u0646.\",\"fr\":\"La proc\\u00e9dure est r\\u00e9alis\\u00e9e sous anesth\\u00e9sie locale, de sorte que les patients ressentent un inconfort minimal. La plupart des patients rapportent ressentir beaucoup moins d\'inconfort qu\'ils ne l\'avaient pr\\u00e9vu.\",\"ru\":\"\\u041f\\u0440\\u043e\\u0446\\u0435\\u0434\\u0443\\u0440\\u0430 \\u043f\\u0440\\u043e\\u0432\\u043e\\u0434\\u0438\\u0442\\u0441\\u044f \\u043f\\u043e\\u0434 \\u043c\\u0435\\u0441\\u0442\\u043d\\u043e\\u0439 \\u0430\\u043d\\u0435\\u0441\\u0442\\u0435\\u0437\\u0438\\u0435\\u0439, \\u043f\\u043e\\u044d\\u0442\\u043e\\u043c\\u0443 \\u043f\\u0430\\u0446\\u0438\\u0435\\u043d\\u0442\\u044b \\u043e\\u0449\\u0443\\u0449\\u0430\\u044e\\u0442 \\u043c\\u0438\\u043d\\u0438\\u043c\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0434\\u0438\\u0441\\u043a\\u043e\\u043c\\u0444\\u043e\\u0440\\u0442. \\u0411\\u043e\\u043b\\u044c\\u0448\\u0438\\u043d\\u0441\\u0442\\u0432\\u043e \\u043f\\u0430\\u0446\\u0438\\u0435\\u043d\\u0442\\u043e\\u0432 \\u043e\\u0442\\u043c\\u0435\\u0447\\u0430\\u044e\\u0442, \\u0447\\u0442\\u043e \\u043f\\u0440\\u043e\\u0446\\u0435\\u0434\\u0443\\u0440\\u0430 \\u043f\\u0440\\u043e\\u0445\\u043e\\u0434\\u0438\\u0442 \\u0433\\u043e\\u0440\\u0430\\u0437\\u0434\\u043e \\u043b\\u0435\\u0433\\u0447\\u0435, \\u0447\\u0435\\u043c \\u043e\\u043d\\u0438 \\u043e\\u0436\\u0438\\u0434\\u0430\\u043b\\u0438.\"}', 1, '2026-04-07 17:01:53', '2026-04-09 19:15:30'),
(5, '{\"en\":\"How long is the recovery time\",\"ar\":\"\\u0645\\u0627 \\u0647\\u064a \\u0645\\u062f\\u0629 \\u0641\\u062a\\u0631\\u0629 \\u0627\\u0644\\u062a\\u0639\\u0627\\u0641\\u064a\\u061f\",\"fr\":\"Quelle est la dur\\u00e9e de la p\\u00e9riode de r\\u00e9cup\\u00e9ration ?\",\"ru\":\"\\u0421\\u043a\\u043e\\u043b\\u044c\\u043a\\u043e \\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u0438 \\u0437\\u0430\\u043d\\u0438\\u043c\\u0430\\u0435\\u0442 \\u0432\\u043e\\u0441\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u0435?\"}', '{\"en\":\"Most patients recover within a few days, while full healing may take a few months\",\"ar\":\"\\u064a\\u062a\\u0639\\u0627\\u0641\\u0649 \\u0645\\u0639\\u0638\\u0645 \\u0627\\u0644\\u0645\\u0631\\u0636\\u0649 \\u0641\\u064a \\u063a\\u0636\\u0648\\u0646 \\u0623\\u064a\\u0627\\u0645 \\u0642\\u0644\\u064a\\u0644\\u0629\\u060c \\u0628\\u064a\\u0646\\u0645\\u0627 \\u0642\\u062f \\u064a\\u0633\\u062a\\u063a\\u0631\\u0642 \\u0627\\u0644\\u0634\\u0641\\u0627\\u0621 \\u0627\\u0644\\u062a\\u0627\\u0645 \\u0628\\u0636\\u0639\\u0629 \\u0623\\u0634\\u0647\\u0631 \\u062d\\u062a\\u0649 \\u062a\\u0646\\u062f\\u0645\\u062c \\u0627\\u0644\\u063a\\u0631\\u0633\\u0629 \\u0645\\u0639 \\u0627\\u0644\\u0639\\u0638\\u0627\\u0645.\",\"fr\":\"La plupart des patients se r\\u00e9tablissent en quelques jours, tandis que la cicatrisation compl\\u00e8te peut prendre quelques mois, le temps que l\'implant s\'int\\u00e8gre \\u00e0 l\'os.\",\"ru\":\"\\u0411\\u043e\\u043b\\u044c\\u0448\\u0438\\u043d\\u0441\\u0442\\u0432\\u043e \\u043f\\u0430\\u0446\\u0438\\u0435\\u043d\\u0442\\u043e\\u0432 \\u0432\\u043e\\u0441\\u0441\\u0442\\u0430\\u043d\\u0430\\u0432\\u043b\\u0438\\u0432\\u0430\\u044e\\u0442\\u0441\\u044f \\u0432 \\u0442\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435 \\u043d\\u0435\\u0441\\u043a\\u043e\\u043b\\u044c\\u043a\\u0438\\u0445 \\u0434\\u043d\\u0435\\u0439, \\u0432 \\u0442\\u043e \\u0432\\u0440\\u0435\\u043c\\u044f \\u043a\\u0430\\u043a \\u043f\\u043e\\u043b\\u043d\\u043e\\u0435 \\u0437\\u0430\\u0436\\u0438\\u0432\\u043b\\u0435\\u043d\\u0438\\u0435 \\u043c\\u043e\\u0436\\u0435\\u0442 \\u0437\\u0430\\u043d\\u044f\\u0442\\u044c \\u043d\\u0435\\u0441\\u043a\\u043e\\u043b\\u044c\\u043a\\u043e \\u043c\\u0435\\u0441\\u044f\\u0446\\u0435\\u0432, \\u043f\\u043e\\u043a\\u0430 \\u0438\\u043c\\u043f\\u043b\\u0430\\u043d\\u0442\\u0430\\u0442 \\u043f\\u0440\\u0438\\u0436\\u0438\\u0432\\u0430\\u0435\\u0442\\u0441\\u044f \\u0432 \\u043a\\u043e\\u0441\\u0442\\u0438.\"}', 1, '2026-04-07 17:02:07', '2026-04-09 19:16:58'),
(6, '{\"en\":\"Why choose Turkey for dental implants\",\"ar\":\"\\u0644\\u0645\\u0627\\u0630\\u0627 \\u062a\\u062e\\u062a\\u0627\\u0631 \\u062a\\u0631\\u0643\\u064a\\u0627 \\u0644\\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0623\\u0633\\u0646\\u0627\\u0646\\u061f\",\"fr\":\"ourquoi choisir la Turquie pour les implants dentaires ?\",\"ru\":\"\\u041f\\u043e\\u0447\\u0435\\u043c\\u0443 \\u0441\\u0442\\u043e\\u0438\\u0442 \\u0432\\u044b\\u0431\\u0440\\u0430\\u0442\\u044c \\u0422\\u0443\\u0440\\u0446\\u0438\\u044e \\u0434\\u043b\\u044f \\u0438\\u043c\\u043f\\u043b\\u0430\\u043d\\u0442\\u0430\\u0446\\u0438\\u0438 \\u0437\\u0443\\u0431\\u043e\\u0432?\"}', '{\"en\":\"Turkey offers high-quality treatment, experienced doctors, and affordable prices\",\"ar\":\"Answer: \\u062a\\u0642\\u062f\\u0645 \\u062a\\u0631\\u0643\\u064a\\u0627 \\u0639\\u0644\\u0627\\u062c\\u0627\\u064b \\u0639\\u0627\\u0644\\u064a \\u0627\\u0644\\u062c\\u0648\\u062f\\u0629\\u060c \\u0648\\u0623\\u0637\\u0628\\u0627\\u0621 \\u0630\\u0648\\u064a \\u062e\\u0628\\u0631\\u0629 \\u0639\\u0627\\u0644\\u0645\\u064a\\u0629\\u060c \\u0648\\u0623\\u0633\\u0639\\u0627\\u0631\\u0627\\u064b \\u0645\\u0639\\u0642\\u0648\\u0644\\u0629\\u060c \\u0628\\u0627\\u0644\\u0625\\u0636\\u0627\\u0641\\u0629 \\u0625\\u0644\\u0649 \\u0641\\u0631\\u0635\\u0629 \\u0627\\u0644\\u0627\\u0633\\u062a\\u0645\\u062a\\u0627\\u0639 \\u0628\\u0639\\u0637\\u0644\\u0629 \\u062c\\u0645\\u064a\\u0644\\u0629 \\u0641\\u064a \\u0648\\u062c\\u0647\\u0629 \\u062a\\u0627\\u0631\\u064a\\u062e\\u064a\\u0629 \\u0639\\u0631\\u064a\\u0642\\u0629.\",\"fr\":\"La Turquie propose des traitements de haute qualit\\u00e9, des m\\u00e9decins exp\\u00e9riment\\u00e9s de renomm\\u00e9e mondiale et des prix abordables, le tout combin\\u00e9 \\u00e0 l\'opportunit\\u00e9 de passer de superbes vacances dans une destination historique.\",\"ru\":\"\\u0422\\u0443\\u0440\\u0446\\u0438\\u044f \\u043f\\u0440\\u0435\\u0434\\u043b\\u0430\\u0433\\u0430\\u0435\\u0442 \\u0432\\u044b\\u0441\\u043e\\u043a\\u043e\\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e\\u0435 \\u043b\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435, \\u043e\\u043f\\u044b\\u0442\\u043d\\u044b\\u0445 \\u0432\\u0440\\u0430\\u0447\\u0435\\u0439 \\u0441 \\u043c\\u0438\\u0440\\u043e\\u0432\\u044b\\u043c \\u0438\\u043c\\u0435\\u043d\\u0435\\u043c \\u0438 \\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u043d\\u044b\\u0435 \\u0446\\u0435\\u043d\\u044b \\u0432 \\u0441\\u043e\\u0447\\u0435\\u0442\\u0430\\u043d\\u0438\\u0438 \\u0441 \\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u043e\\u0441\\u0442\\u044c\\u044e \\u043f\\u0440\\u043e\\u0432\\u0435\\u0441\\u0442\\u0438 \\u043f\\u0440\\u0435\\u043a\\u0440\\u0430\\u0441\\u043d\\u044b\\u0439 \\u043e\\u0442\\u043f\\u0443\\u0441\\u043a \\u0432 \\u0438\\u0441\\u0442\\u043e\\u0440\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u043c \\u043c\\u0435\\u0441\\u0442\\u0435.\"}', 1, '2026-04-07 17:02:21', '2026-04-09 19:18:36'),
(7, '{\"en\":\"Question: When will I see the full results of my hair transplant?\",\"ar\":\"\\u0645\\u062a\\u0649 \\u0633\\u0623\\u0631\\u0649 \\u0627\\u0644\\u0646\\u062a\\u0627\\u0626\\u062c \\u0627\\u0644\\u0646\\u0647\\u0627\\u0626\\u064a\\u0629 \\u0644\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0634\\u0639\\u0631\\u061f\",\"fr\":\"Quand verrai-je les r\\u00e9sultats complets de ma greffe de cheveux ?\",\"ru\":\"\\u041a\\u043e\\u0433\\u0434\\u0430 \\u044f \\u0443\\u0432\\u0438\\u0436\\u0443 \\u043e\\u043a\\u043e\\u043d\\u0447\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442 \\u043f\\u0435\\u0440\\u0435\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0432\\u043e\\u043b\\u043e\\u0441?\"}', '{\"en\":\"You will start to see new growth after 3-4 months. However, the final, full density results are typically achieved between 12 to 18 months after the procedure.\",\"ar\":\"\\u0633\\u062a\\u0628\\u062f\\u0623 \\u0641\\u064a \\u0631\\u0624\\u064a\\u0629 \\u0646\\u0645\\u0648 \\u062c\\u062f\\u064a\\u062f \\u0628\\u0639\\u062f 3-4 \\u0623\\u0634\\u0647\\u0631. \\u0648\\u0645\\u0639 \\u0630\\u0644\\u0643\\u060c \\u064a\\u062a\\u0645 \\u062a\\u062d\\u0642\\u064a\\u0642 \\u0627\\u0644\\u0646\\u062a\\u0627\\u0626\\u062c \\u0627\\u0644\\u0646\\u0647\\u0627\\u0626\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0643\\u062b\\u0627\\u0641\\u0629 \\u0627\\u0644\\u0643\\u0627\\u0645\\u0644\\u0629 \\u0639\\u0627\\u062f\\u0629\\u064b \\u0645\\u0627 \\u0628\\u064a\\u0646 12 \\u0625\\u0644\\u0649 18 \\u0634\\u0647\\u0631\\u0627\\u064b \\u0628\\u0639\\u062f \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629.\",\"fr\":\"ous commencerez \\u00e0 voir la repousse apr\\u00e8s 3-4 mois. Cependant, les r\\u00e9sultats finaux et la densit\\u00e9 totale sont g\\u00e9n\\u00e9ralement atteints entre 12 et 18 mois apr\\u00e8s l\'intervention.\",\"ru\":\"\\u044b \\u043d\\u0430\\u0447\\u043d\\u0435\\u0442\\u0435 \\u0437\\u0430\\u043c\\u0435\\u0447\\u0430\\u0442\\u044c \\u0440\\u043e\\u0441\\u0442 \\u043d\\u043e\\u0432\\u044b\\u0445 \\u0432\\u043e\\u043b\\u043e\\u0441 \\u0447\\u0435\\u0440\\u0435\\u0437 3-4 \\u043c\\u0435\\u0441\\u044f\\u0446\\u0430. \\u041e\\u0434\\u043d\\u0430\\u043a\\u043e \\u043e\\u043a\\u043e\\u043d\\u0447\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442 \\u0438 \\u043f\\u043e\\u043b\\u043d\\u0430\\u044f \\u0433\\u0443\\u0441\\u0442\\u043e\\u0442\\u0430 \\u043e\\u0431\\u044b\\u0447\\u043d\\u043e \\u0434\\u043e\\u0441\\u0442\\u0438\\u0433\\u0430\\u044e\\u0442\\u0441\\u044f \\u0432 \\u043f\\u0435\\u0440\\u0438\\u043e\\u0434 \\u043e\\u0442 12 \\u0434\\u043e 18 \\u043c\\u0435\\u0441\\u044f\\u0446\\u0435\\u0432 \\u043f\\u043e\\u0441\\u043b\\u0435 \\u043f\\u0440\\u043e\\u0446\\u0435\\u0434\\u0443\\u0440\\u044b.\"}', 1, '2026-04-09 19:19:55', '2026-04-09 19:19:55'),
(8, '{\"en\":\"Do you provide hotel accommodation and airport transfers?\",\"ar\":\"\\u0647\\u0644 \\u062a\\u0648\\u0641\\u0631\\u0648\\u0646 \\u0627\\u0644\\u0625\\u0642\\u0627\\u0645\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0641\\u0646\\u0627\\u062f\\u0642 \\u0648\\u0627\\u0644\\u0646\\u0642\\u0644 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0637\\u0627\\u0631\\u061f\",\"fr\":\"Proposez-vous l\'h\\u00e9bergement \\u00e0 l\'h\\u00f4tel et les transferts a\\u00e9roport ?\",\"ru\":\"\\u041f\\u0440\\u0435\\u0434\\u043e\\u0441\\u0442\\u0430\\u0432\\u043b\\u044f\\u0435\\u0442\\u0435 \\u043b\\u0438 \\u0432\\u044b \\u043f\\u0440\\u043e\\u0436\\u0438\\u0432\\u0430\\u043d\\u0438\\u0435 \\u0432 \\u043e\\u0442\\u0435\\u043b\\u0435 \\u0438 \\u0442\\u0440\\u0430\\u043d\\u0441\\u0444\\u0435\\u0440 \\u0438\\u0437 \\u0430\\u044d\\u0440\\u043e\\u043f\\u043e\\u0440\\u0442\\u0430?\"}', '{\"en\":\"Yes, all our packages include 5-star hotel accommodation and VIP transfers between the airport, hotel, and clinic for a stress-free experience.\",\"ar\":\"\\u0646\\u0639\\u0645\\u060c \\u062a\\u0634\\u0645\\u0644 \\u062c\\u0645\\u064a\\u0639 \\u0628\\u0627\\u0642\\u0627\\u062a\\u0646\\u0627 \\u0625\\u0642\\u0627\\u0645\\u0629 \\u0641\\u064a \\u0641\\u0646\\u0627\\u062f\\u0642 5 \\u0646\\u062c\\u0648\\u0645 \\u0648\\u0646\\u0642\\u0644 VIP \\u0628\\u064a\\u0646 \\u0627\\u0644\\u0645\\u0637\\u0627\\u0631 \\u0648\\u0627\\u0644\\u0641\\u0646\\u062f\\u0642 \\u0648\\u0627\\u0644\\u0639\\u064a\\u0627\\u062f\\u0629 \\u0644\\u0636\\u0645\\u0627\\u0646 \\u062a\\u062c\\u0631\\u0628\\u0629 \\u0645\\u0631\\u064a\\u062d\\u0629 \\u0648\\u062e\\u0627\\u0644\\u064a\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u062a\\u0648\\u062a\\u0631.\",\"fr\":\"Oui, tous nos forfaits incluent l\'h\\u00e9bergement en h\\u00f4tel 5 \\u00e9toiles et les transferts VIP entre l\'a\\u00e9roport, l\'h\\u00f4tel et la clinique pour une exp\\u00e9rience sans stress.\",\"ru\":\"\\u0414\\u0430, \\u0432\\u0441\\u0435 \\u043d\\u0430\\u0448\\u0438 \\u043f\\u0430\\u043a\\u0435\\u0442\\u044b \\u0432\\u043a\\u043b\\u044e\\u0447\\u0430\\u044e\\u0442 \\u043f\\u0440\\u043e\\u0436\\u0438\\u0432\\u0430\\u043d\\u0438\\u0435 \\u0432 5-\\u0437\\u0432\\u0435\\u0437\\u0434\\u043e\\u0447\\u043d\\u043e\\u043c \\u043e\\u0442\\u0435\\u043b\\u0435 \\u0438 VIP-\\u0442\\u0440\\u0430\\u043d\\u0441\\u0444\\u0435\\u0440 \\u043c\\u0435\\u0436\\u0434\\u0443 \\u0430\\u044d\\u0440\\u043e\\u043f\\u043e\\u0440\\u0442\\u043e\\u043c, \\u043e\\u0442\\u0435\\u043b\\u0435\\u043c \\u0438 \\u043a\\u043b\\u0438\\u043d\\u0438\\u043a\\u043e\\u0439 \\u0434\\u043b\\u044f \\u0432\\u0430\\u0448\\u0435\\u0433\\u043e \\u043c\\u0430\\u043a\\u0441\\u0438\\u043c\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u043a\\u043e\\u043c\\u0444\\u043e\\u0440\\u0442\\u0430.\"}', 1, '2026-04-09 19:20:56', '2026-04-09 19:20:56');

