(3, '{\"en\":\"Free Consultation\",\"ar\":\"\\u0627\\u0633\\u062a\\u0634\\u0627\\u0631\\u0629 \\u0645\\u062c\\u0627\\u0646\\u064a\\u0629\",\"fr\":\"Consultation Gratuite\",\"ru\":\"\\u0411\\u0435\\u0441\\u043f\\u043b\\u0430\\u0442\\u043d\\u0430\\u044f \\u043a\\u043e\\u043d\\u0441\\u0443\\u043b\\u044c\\u0442\\u0430\\u0446\\u0438\\u044f\"}', '{\"en\":\"Contact us and share your case details. Our specialists will evaluate your condition and provide a personalized treatment plan.\",\"ar\":\"\\u0627\\u062a\\u0635\\u0644 \\u0628\\u0646\\u0627 \\u0648\\u0634\\u0627\\u0631\\u0643 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u062d\\u0627\\u0644\\u062a\\u0643. \\u0633\\u064a\\u0642\\u0648\\u0645 \\u0623\\u062e\\u0635\\u0627\\u0626\\u064a\\u0648\\u0646\\u0627 \\u0628\\u062a\\u0642\\u064a\\u064a\\u0645 \\u062d\\u0627\\u0644\\u062a\\u0643 \\u0648\\u062a\\u0642\\u062f\\u064a\\u0645 \\u062e\\u0637\\u0629 \\u0639\\u0644\\u0627\\u062c \\u0645\\u062e\\u0635\\u0635\\u0629 \\u0644\\u0643.\",\"fr\":\"Contactez-nous et partagez les d\\u00e9tails de votre cas. Nos sp\\u00e9cialistes \\u00e9valueront votre situation et vous proposeront un plan de traitement personnalis\\u00e9.\",\"ru\":\"\\u0421\\u0432\\u044f\\u0436\\u0438\\u0442\\u0435\\u0441\\u044c \\u0441 \\u043d\\u0430\\u043c\\u0438 \\u0438 \\u043f\\u043e\\u0434\\u0435\\u043b\\u0438\\u0442\\u0435\\u0441\\u044c \\u0434\\u0435\\u0442\\u0430\\u043b\\u044f\\u043c\\u0438 \\u0432\\u0430\\u0448\\u0435\\u0433\\u043e \\u0441\\u043b\\u0443\\u0447\\u0430\\u044f. \\u041d\\u0430\\u0448\\u0438 \\u0441\\u043f\\u0435\\u0446\\u0438\\u0430\\u043b\\u0438\\u0441\\u0442\\u044b \\u043e\\u0446\\u0435\\u043d\\u044f\\u0442 \\u0432\\u0430\\u0448\\u0435 \\u0441\\u043e\\u0441\\u0442\\u043e\\u044f\\u043d\\u0438\\u0435 \\u0438 \\u043f\\u0440\\u0435\\u0434\\u043e\\u0441\\u0442\\u0430\\u0432\\u044f\\u0442 \\u0438\\u043d\\u0434\\u0438\\u0432\\u0438\\u0434\\u0443\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u043f\\u043b\\u0430\\u043d \\u043b\\u0435\\u0447\\u0435\\u043d\\u0438\\u044f.\"}', 'Check', 1, 1, '2026-04-07 17:04:59', '2026-04-09 19:32:12'),
(4, '{\"en\":\"Treatment Planning\",\"ar\":\"\\u062a\\u062e\\u0637\\u064a\\u0637 \\u0627\\u0644\\u0639\\u0644\\u0627\\u062c\",\"fr\":\"Planification du Traitement\",\"ru\":\"\\u041f\\u043b\\u0430\\u043d\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 \\u043b\\u0435\\u0447\\u0435\\u043d\\u0438\\u044f\"}', '{\"en\":\"We create a customized treatment plan including procedures, timeline, and cost based on your needs.\",\"ar\":\"\\u0646\\u0642\\u0648\\u0645 \\u0628\\u0625\\u0646\\u0634\\u0627\\u0621 \\u062e\\u0637\\u0629 \\u0639\\u0644\\u0627\\u062c \\u0645\\u062e\\u0635\\u0635\\u0629 \\u062a\\u062a\\u0636\\u0645\\u0646 \\u0627\\u0644\\u0625\\u062c\\u0631\\u0627\\u0621\\u0627\\u062a \\u0648\\u0627\\u0644\\u062c\\u062f\\u0648\\u0644 \\u0627\\u0644\\u0632\\u0645\\u0646\\u064a \\u0648\\u0627\\u0644\\u062a\\u0643\\u0644\\u0641\\u0629 \\u0628\\u0646\\u0627\\u0621\\u064b \\u0639\\u0644\\u0649 \\u0627\\u062d\\u062a\\u064a\\u0627\\u062c\\u0627\\u062a\\u0643.\",\"fr\":\"Nous cr\\u00e9ons un plan de traitement personnalis\\u00e9 incluant les proc\\u00e9dures, le calendrier et les co\\u00fbts en fonction de vos besoins.\",\"ru\":\"\\u041c\\u044b \\u0441\\u043e\\u0437\\u0434\\u0430\\u0435\\u043c \\u0438\\u043d\\u0434\\u0438\\u0432\\u0438\\u0434\\u0443\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u043f\\u043b\\u0430\\u043d \\u043b\\u0435\\u0447\\u0435\\u043d\\u0438\\u044f, \\u0432\\u043a\\u043b\\u044e\\u0447\\u0430\\u044e\\u0449\\u0438\\u0439 \\u043f\\u0440\\u043e\\u0446\\u0435\\u0434\\u0443\\u0440\\u044b, \\u0441\\u0440\\u043e\\u043a\\u0438 \\u0438 \\u0441\\u0442\\u043e\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c, \\u0438\\u0441\\u0445\\u043e\\u0434\\u044f \\u0438\\u0437 \\u0432\\u0430\\u0448\\u0438\\u0445 \\u043f\\u043e\\u0442\\u0440\\u0435\\u0431\\u043d\\u043e\\u0441\\u0442\\u0435\\u0439.\"}', 'HelpCircle', 2, 1, '2026-04-07 17:05:24', '2026-04-09 19:48:01'),
(5, '{\"en\":\"Arrival & Treatment\",\"ar\":\"\\u0627\\u0644\\u0648\\u0635\\u0648\\u0644 \\u0648\\u0627\\u0644\\u0639\\u0644\\u0627\\u062c\",\"fr\":\"Arriv\\u00e9e et Traitement\",\"ru\":\"\\u041f\\u0440\\u0438\\u0431\\u044b\\u0442\\u0438\\u0435 \\u0438 \\u043b\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435\"}', '{\"en\":\"Upon arrival in Istanbul, our team assists you from airport pickup to clinic visits and performs your treatment.\",\"ar\":\"\\u0639\\u0646\\u062f \\u0648\\u0635\\u0648\\u0644\\u0643 \\u0625\\u0644\\u0649 \\u0625\\u0633\\u0637\\u0646\\u0628\\u0648\\u0644\\u060c \\u064a\\u0633\\u0627\\u0639\\u062f\\u0643 \\u0641\\u0631\\u064a\\u0642\\u0646\\u0627 \\u0645\\u0646 \\u0627\\u0644\\u0627\\u0633\\u062a\\u0642\\u0628\\u0627\\u0644 \\u0641\\u064a \\u0627\\u0644\\u0645\\u0637\\u0627\\u0631 \\u0625\\u0644\\u0649 \\u0632\\u064a\\u0627\\u0631\\u0627\\u062a \\u0627\\u0644\\u0639\\u064a\\u0627\\u062f\\u0629 \\u0648\\u064a\\u0642\\u0648\\u0645 \\u0628\\u0625\\u062c\\u0631\\u0627\\u0621 \\u0639\\u0644\\u0627\\u062c\\u0643\",\"fr\":\"\\u00c0 votre arriv\\u00e9e \\u00e0 Istanbul, notre \\u00e9quipe vous accompagne de la prise en charge \\u00e0 l\'a\\u00e9roport jusqu\'aux visites \\u00e0 la clinique ve r\\u00e9alise votre traitement.\",\"ru\":\"\\u041f\\u043e \\u043f\\u0440\\u0438\\u0431\\u044b\\u0442\\u0438\\u0438 \\u0432 \\u0421\\u0442\\u0430\\u043c\\u0431\\u0443\\u043b \\u043d\\u0430\\u0448\\u0430 \\u043a\\u043e\\u043c\\u0430\\u043d\\u0434\\u0430 \\u0441\\u043e\\u043f\\u0440\\u043e\\u0432\\u043e\\u0436\\u0434\\u0430\\u0435\\u0442 \\u0432\\u0430\\u0441 \\u043e\\u0442 \\u0432\\u0441\\u0442\\u0440\\u0435\\u0447\\u0438 \\u0432 \\u0430\\u044d\\u0440\\u043e\\u043f\\u043e\\u0440\\u0442\\u0443 \\u0434\\u043e \\u0432\\u0438\\u0437\\u0438\\u0442\\u043e\\u0432 \\u0432 \\u043a\\u043b\\u0438\\u043d\\u0438\\u043a\\u0443 \\u0438 \\u043f\\u0440\\u043e\\u0432\\u043e\\u0434\\u0438\\u0442 \\u0432\\u0430\\u0448\\u0435 \\u043b\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435.\"}', 'Building2', 3, 1, '2026-04-07 17:05:46', '2026-04-09 19:49:03'),
(6, '{\"en\":\"Recovery & Results\",\"ar\":\"\\u0627\\u0644\\u062a\\u0639\\u0627\\u0641\\u064a \\u0648\\u0627\\u0644\\u0646\\u062a\\u0627\\u0626\\u062c\",\"fr\":\"R\\u00e9cup\\u00e9ration et R\\u00e9sultats\",\"ru\":\"\\u0412\\u043e\\u0441\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u0435 \\u0438 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u044b\"}', '{\"en\":\"After the procedure, you receive follow-up care and enjoy long-lasting, natural results.\",\"ar\":\"\\u0628\\u0639\\u062f \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629\\u060c \\u062a\\u062a\\u0644\\u0642\\u0649 \\u0631\\u0639\\u0627\\u064a\\u0629 \\u0627\\u0644\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u0648\\u062a\\u0633\\u062a\\u0645\\u062a\\u0639 \\u0628\\u0646\\u062a\\u0627\\u0626\\u062c \\u0637\\u0628\\u064a\\u0639\\u064a\\u0629 \\u062a\\u062f\\u0648\\u0645 \\u0637\\u0648\\u064a\\u0644\\u0627\\u064b.\",\"fr\":\"Apr\\u00e8s l\'intervention, vous b\\u00e9n\\u00e9ficiez d\'un suivi post-op\\u00e9ratoire et profitez de r\\u00e9sultats naturels et durables.\",\"ru\":\"\\u041f\\u043e\\u0441\\u043b\\u0435 \\u043f\\u0440\\u043e\\u0446\\u0435\\u0434\\u0443\\u0440\\u044b \\u0432\\u044b \\u043f\\u043e\\u043b\\u0443\\u0447\\u0430\\u0435\\u0442\\u0435 \\u043f\\u043e\\u0441\\u043b\\u0435\\u0434\\u0443\\u044e\\u0449\\u0438\\u0439 \\u0443\\u0445\\u043e\\u0434 \\u0438 \\u043d\\u0430\\u0441\\u043b\\u0430\\u0436\\u0434\\u0430\\u0435\\u0442\\u0435\\u0441\\u044c \\u0434\\u043e\\u043b\\u0433\\u043e\\u0432\\u0435\\u0447\\u043d\\u044b\\u043c\\u0438, \\u0435\\u0441\\u0442\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u043c\\u0438 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u0430\\u043c\\u0438.\"}', 'Award', 4, 1, '2026-04-07 17:06:05', '2026-04-09 19:49:56');

