('whatsapp', '{\"phone_number\":\"+90 541 339 25 69\",\"message\":{\"en\":\"Hello Lumo Clinic, I would like to get more information.\",\"ar\":\"\\u0645\\u0631\\u062d\\u0628\\u064b\\u0627 \\u0644\\u0648\\u0645\\u0648 \\u0643\\u0644\\u064a\\u0646\\u064a\\u0643\\u060c \\u0623\\u0648\\u062f \\u0627\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0645\\u0632\\u064a\\u062f \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a.\",\"fr\":\"Bonjour Lumo Clinic, j\'aimerais avoir plus d\'informations.\",\"ru\":\"\\u0417\\u0434\\u0440\\u0430\\u0432\\u0441\\u0442\\u0432\\u0443\\u0439\\u0442\\u0435, \\u043a\\u043b\\u0438\\u043d\\u0438\\u043a\\u0430 \\u041b\\u0443\\u043c\\u043e, \\u044f \\u0445\\u043e\\u0442\\u0435\\u043b \\u0431\\u044b \\u043f\\u043e\\u043b\\u0443\\u0447\\u0438\\u0442\\u044c \\u0431\\u043e\\u043b\\u044c\\u0448\\u0435 \\u0438\\u043d\\u0444\\u043e\\u0440\\u043c\\u0430\\u0446\\u0438\\u0438.\"},\"enabled\":true}', '2026-04-05 20:03:24', '2026-04-05 20:03:24'),
('why_choose_us_features', '[{\"icon\":\"Award\",\"title\":{\"en\":\"Art & Precision\",\"ar\":\"\\u0627\\u0644\\u0641\\u0646 \\u0648\\u0627\\u0644\\u062f\\u0642\\u0629\",\"fr\":\"Art et Pr\\u00e9cision\",\"ru\":\"\\u0418\\u0441\\u043a\\u0443\\u0441\\u0441\\u0442\\u0432\\u043e \\u0438 \\u0442\\u043e\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c\"},\"desc\":{\"en\":\"esthetic designs specifically tailored to highlight your unique features.\",\"ar\":\"\\u062a\\u0635\\u0627\\u0645\\u064a\\u0645 \\u062c\\u0645\\u0627\\u0644\\u064a\\u0629 \\u0645\\u0635\\u0645\\u0645\\u0629 \\u062e\\u0635\\u064a\\u0635\\u0627\\u064b \\u0644\\u0645\\u064a\\u0632\\u0627\\u062a\\u0643 \\u0627\\u0644\\u0641\\u0631\\u064a\\u062f\\u0629.\",\"fr\":\"es designs esth\\u00e9tiques con\\u00e7us sur mesure pour vos traits uniques.\",\"ru\":\"\\u042d\\u0441\\u0442\\u0435\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d, \\u0440\\u0430\\u0437\\u0440\\u0430\\u0431\\u043e\\u0442\\u0430\\u043d\\u043d\\u044b\\u0439 \\u0441\\u043f\\u0435\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u043e \\u0434\\u043b\\u044f \\u0432\\u0430\\u0448\\u0438\\u0445 \\u0443\\u043d\\u0438\\u043a\\u0430\\u043b\\u044c\\u043d\\u044b\\u0445 \\u0447\\u0435\\u0440\\u0442.\"}},{\"icon\":\"Award\",\"title\":{\"en\":\"Comprehensive Packages\",\"ar\":\"\\u0628\\u0627\\u0642\\u0627\\u062a \\u0634\\u0627\\u0645\\u0644\\u0629\",\"fr\":\"Forfaits Complets\",\"ru\":\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u043d\\u044b\\u0435 \\u043f\\u0430\\u043a\\u0435\\u0442\\u044b\"},\"desc\":{\"en\":\"Treatment, accommodation, and transfers are all included.\",\"ar\":\"\\u0627\\u0644\\u0639\\u0644\\u0627\\u062c \\u0648\\u0627\\u0644\\u0625\\u0642\\u0627\\u0645\\u0629 \\u0648\\u0627\\u0644\\u0627\\u0646\\u062a\\u0642\\u0627\\u0644\\u0627\\u062a \\u0645\\u0634\\u0645\\u0648\\u0644\\u0629.\",\"fr\":\"Le traitement, l\'h\\u00e9bergement et les transferts sont inclus.\",\"ru\":\"\\u041b\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435, \\u043f\\u0440\\u043e\\u0436\\u0438\\u0432\\u0430\\u043d\\u0438\\u0435 \\u0438 \\u0442\\u0440\\u0430\\u043d\\u0441\\u0444\\u0435\\u0440 \\u0432\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u044b \\u0432 \\u0441\\u0442\\u043e\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c.\"}},{\"icon\":\"Award\",\"title\":{\"en\":\"Expert Medical Team\",\"ar\":\"\\u0641\\u0631\\u064a\\u0642 \\u0637\\u0628\\u064a \\u062e\\u0628\\u064a\\u0631\",\"fr\":\"\\u00c9quipe M\\u00e9dicale Experte\",\"ru\":\"\\u042d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0442\\u043d\\u0430\\u044f \\u043c\\u0435\\u0434\\u0438\\u0446\\u0438\\u043d\\u0441\\u043a\\u0430\\u044f \\u043a\\u043e\\u043c\\u0430\\u043d\\u0434\\u0430\"},\"desc\":{\"en\":\"A team of world-class doctors and surgeons committed to providing the best care.\",\"ar\":\"\\u0646\\u062e\\u0628\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0623\\u0637\\u0628\\u0627\\u0621 \\u0648\\u0627\\u0644\\u062c\\u0631\\u0627\\u062d\\u064a\\u0646 \\u0630\\u0648\\u064a \\u0627\\u0644\\u062e\\u0628\\u0631\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645\\u064a\\u0629 \\u0644\\u0636\\u0645\\u0627\\u0646 \\u0623\\u0641\\u0636\\u0644 \\u0627\\u0644\\u0631\\u0639\\u0627\\u064a\\u0629.\",\"fr\":\"Une \\u00e9quipe de m\\u00e9decins et chirurgiens de classe mondiale d\\u00e9vou\\u00e9s aux meilleurs soins.\",\"ru\":\"\\u041a\\u043e\\u043c\\u0430\\u043d\\u0434\\u0430 \\u0432\\u0440\\u0430\\u0447\\u0435\\u0439 \\u0438 \\u0445\\u0438\\u0440\\u0443\\u0440\\u0433\\u043e\\u0432 \\u043c\\u0438\\u0440\\u043e\\u0432\\u043e\\u0433\\u043e \\u0443\\u0440\\u043e\\u0432\\u043d\\u044f, \\u0441\\u0442\\u0440\\u0435\\u043c\\u044f\\u0449\\u0438\\u0445\\u0441\\u044f \\u043e\\u0431\\u0435\\u0441\\u043f\\u0435\\u0447\\u0438\\u0442\\u044c \\u043b\\u0443\\u0447\\u0448\\u0438\\u0439 \\u0443\\u0445\\u043e\\u0434.\"}},{\"icon\":\"Award\",\"title\":{\"en\":\"Advanced Technology\",\"ar\":\"\\u062a\\u0642\\u0646\\u064a\\u0627\\u062a \\u0645\\u062a\\u0637\\u0648\\u0631\\u0629\",\"fr\":\"Technologie Avanc\\u00e9e\",\"ru\":\"\\u041f\\u0435\\u0440\\u0435\\u0434\\u043e\\u0432\\u044b\\u0435 \\u0442\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u0438\"},\"desc\":{\"en\":\"We use the latest internationally certified medical devices and techniques for precise results.\",\"ar\":\"\\u0646\\u0633\\u062a\\u062e\\u062f\\u0645 \\u0623\\u062d\\u062f\\u062b \\u0627\\u0644\\u0623\\u062c\\u0647\\u0632\\u0629 \\u0648\\u0627\\u0644\\u062a\\u0642\\u0646\\u064a\\u0627\\u062a \\u0627\\u0644\\u0637\\u0628\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0639\\u062a\\u0645\\u062f\\u0629 \\u062f\\u0648\\u0644\\u064a\\u0627\\u064b \\u0644\\u0636\\u0645\\u0627\\u0646 \\u0646\\u062a\\u0627\\u0626\\u062c \\u062f\\u0642\\u064a\\u0642\\u0629.\",\"fr\":\"Nous utilisons les derniers dispositifs et techniques m\\u00e9dicaux certifi\\u00e9s pour des r\\u00e9sultats pr\\u00e9cis.\",\"ru\":\"\\u041c\\u044b \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u0443\\u0435\\u043c \\u043d\\u043e\\u0432\\u0435\\u0439\\u0448\\u0435\\u0435 \\u0441\\u0435\\u0440\\u0442\\u0438\\u0444\\u0438\\u0446\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0435 \\u043e\\u0431\\u043e\\u0440\\u0443\\u0434\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 \\u0438 \\u043c\\u0435\\u0442\\u043e\\u0434\\u044b \\u0434\\u043b\\u044f \\u0434\\u043e\\u0441\\u0442\\u0438\\u0436\\u0435\\u043d\\u0438\\u044f \\u0442\\u043e\\u0447\\u043d\\u044b\\u0445 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u043e\\u0432.\"}}]', '2026-04-05 20:03:24', '2026-04-08 21:12:42');

