(2, 'hollywood-smile', '{\"en\":\"Dental\",\"ar\":\"\\u0627\\u0644\\u0623\\u0633\\u0646\\u0627\\u0646\",\"fr\":\"Dentaire\",\"ru\":\"\\u0421\\u0442\\u043e\\u043c\\u0430\\u0442\\u043e\\u043b\\u043e\\u0433\\u0438\\u044f\"}', '{\"en\":\"Hollywood Smile\",\"ar\":\"\\u0625\\u0628\\u062a\\u0633\\u0627\\u0645\\u0629 \\u0647\\u0648\\u0644\\u064a\\u0648\\u062f\",\"fr\":\"Sourire Hollywood\",\"ru\":\"\\u0413\\u043e\\u043b\\u043b\\u0438\\u0432\\u0443\\u0434\\u0441\\u043a\\u0430\\u044f \\u0423\\u043b\\u044b\\u0431\\u043a\\u0430\"}', 58, 60, 59, '{\"en\":\"Achieve a flawless, radiant, and perfectly aligned white smile with our professional Hollywood Smile service in Istanbul. Personalized designs tailored to your facial features with the highest quality standards.\",\"ar\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0628\\u062a\\u0633\\u0627\\u0645\\u0629 \\u0628\\u064a\\u0636\\u0627\\u0621 \\u0645\\u0634\\u0631\\u0641\\u0629 \\u0648\\u0645\\u062a\\u0646\\u0627\\u0633\\u0642\\u0629 \\u062a\\u0645\\u0627\\u0645\\u0627\\u064b \\u0645\\u0639 \\u062e\\u062f\\u0645\\u0629 \\u0625\\u0628\\u062a\\u0633\\u0627\\u0645\\u0629 \\u0647\\u0648\\u0644\\u064a\\u0648\\u062f \\u0627\\u0644\\u0627\\u062d\\u062a\\u0631\\u0627\\u0641\\u064a\\u0629 \\u0641\\u064a \\u0639\\u064a\\u0627\\u062f\\u062a\\u0646\\u0627 \\u0628\\u0625\\u0633\\u0637\\u0646\\u0628\\u0648\\u0644. \\u062a\\u0635\\u0645\\u064a\\u0645 \\u0645\\u062e\\u0635\\u0635 \\u0644\\u064a\\u0646\\u0627\\u0633\\u0628 \\u0645\\u0644\\u0627\\u0645\\u062d \\u0648\\u062c\\u0647\\u0643 \\u0628\\u0623\\u0639\\u0644\\u0649 \\u0645\\u0639\\u0627\\u064a\\u064a\\u0631 \\u0627\\u0644\\u062c\\u0648\\u062f\\u0629.\",\"fr\":\"Obtenez un sourire \\u00e9clatant, harmonieux et parfaitement blanc gr\\u00e2ce \\u00e0 notre service professionnel de Sourire Hollywood \\u00e0 Istanbul. Un design sur mesure adapt\\u00e9 \\u00e0 vos traits pour un r\\u00e9sultat d\'une qualit\\u00e9 exceptionnelle.\",\"ru\":\"\\u041e\\u0431\\u0440\\u0435\\u0442\\u0438\\u0442\\u0435 \\u0431\\u0435\\u0437\\u0443\\u043f\\u0440\\u0435\\u0447\\u043d\\u0443\\u044e, \\u0441\\u0438\\u044f\\u044e\\u0449\\u0443\\u044e \\u0438 \\u0438\\u0434\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e \\u0440\\u043e\\u0432\\u043d\\u0443\\u044e \\u0431\\u0435\\u043b\\u043e\\u0441\\u043d\\u0435\\u0436\\u043d\\u0443\\u044e \\u0443\\u043b\\u044b\\u0431\\u043a\\u0443 \\u0441 \\u043d\\u0430\\u0448\\u0435\\u0439 \\u043f\\u0440\\u043e\\u0444\\u0435\\u0441\\u0441\\u0438\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0443\\u0441\\u043b\\u0443\\u0433\\u043e\\u0439 \\u00ab\\u0413\\u043e\\u043b\\u043b\\u0438\\u0432\\u0443\\u0434\\u0441\\u043a\\u0430\\u044f \\u0443\\u043b\\u044b\\u0431\\u043a\\u0430\\u00bb \\u0432 \\u0421\\u0442\\u0430\\u043c\\u0431\\u0443\\u043b\\u0435. \\u0418\\u043d\\u0434\\u0438\\u0432\\u0438\\u0434\\u0443\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d, \\u0441\\u043e\\u0437\\u0434\\u0430\\u043d\\u043d\\u044b\\u0439 \\u0441 \\u0443\\u0447\\u0435\\u0442\\u043e\\u043c \\u0432\\u0430\\u0448\\u0438\\u0445 \\u0447\\u0435\\u0440\\u0442 \\u043b\\u0438\\u0446\\u0430 \\u0438 \\u0432\\u044b\\u0441\\u043e\\u0447\\u0430\\u0439\\u0448\\u0438\\u0445 \\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442\\u043e\\u0432 \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0430.\"}', 100.00, '{\"en\":\"5-7 Days\",\"ar\":\"5-7 \\u0623\\u064a\\u0627\\u0645\",\"fr\":\"5-7 Jours\",\"ru\":\"5-7 \\u0434\\u043d\\u0435\\u0439\"}', '{\"en\":[\"Custom Digital Smile Design (DSD)\",\"Premium Quality Porcelain Veneers & Lumineers\",\"Long-Lasting Professional Teeth Whitening\",\"Instant & Life-Changing Aesthetic Results\",\"World-Class Cosmetic Dentistry Experts\"],\"ar\":[\"\\u062a\\u0635\\u0645\\u064a\\u0645 \\u0631\\u0642\\u0645\\u064a \\u0645\\u062e\\u0635\\u0635 \\u0644\\u0644\\u0627\\u0628\\u062a\\u0633\\u0627\\u0645\\u0629\",\"\\u0642\\u0634\\u0648\\u0631 \\u062e\\u0632\\u0641\\u064a\\u0629 (\\u0641\\u064a\\u0646\\u064a\\u0631) \\u0639\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062c\\u0648\\u062f\\u0629\",\"\\u062a\\u0628\\u064a\\u064a\\u0636 \\u0623\\u0633\\u0646\\u0627\\u0646 \\u0627\\u062d\\u062a\\u0631\\u0627\\u0641\\u064a \\u0648\\u062f\\u0627\\u0626\\u0645\",\"\\u0646\\u062a\\u0627\\u0626\\u062c \\u0641\\u0648\\u0631\\u064a\\u0629 \\u0648\\u0645\\u0630\\u0647\\u0644\\u0629\",\"\\u0637\\u0627\\u0642\\u0645 \\u0637\\u0628\\u064a \\u062a\\u062c\\u0645\\u064a\\u0644\\u064a \\u0630\\u0648 \\u062e\\u0628\\u0631\\u0629 \\u0639\\u0627\\u0644\\u0645\\u064a\\u0629\"],\"fr\":[\"Conception num\\u00e9rique du sourire sur mesure (DSD)\",\"Facettes en porcelaine de qualit\\u00e9 premium\",\"Blanchiment dentaire professionnel durable\",\"R\\u00e9sultats esth\\u00e9tiques imm\\u00e9diats et spectaculaires\",\"Experts en dentisterie esth\\u00e9tique de renomm\\u00e9e mondiale\"],\"ru\":[\"\\u0426\\u0438\\u0444\\u0440\\u043e\\u0432\\u043e\\u0439 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u0443\\u043b\\u044b\\u0431\\u043a\\u0438 (DSD)\",\"\\u0412\\u0438\\u043d\\u0438\\u0440\\u044b \\u0438 \\u043b\\u044e\\u043c\\u0438\\u043d\\u0438\\u0440\\u044b \\u043f\\u0440\\u0435\\u043c\\u0438\\u0443\\u043c-\\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0430\",\"\\u0414\\u043e\\u043b\\u0433\\u043e\\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u043e\\u0435 \\u043f\\u0440\\u043e\\u0444\\u0435\\u0441\\u0441\\u0438\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0435 \\u043e\\u0442\\u0431\\u0435\\u043b\\u0438\\u0432\\u0430\\u043d\\u0438\\u0435\",\"\\u042d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0442\\u044b \\u043c\\u0438\\u0440\\u043e\\u0432\\u043e\\u0433\\u043e \\u0443\\u0440\\u043e\\u0432\\u043d\\u044f \\u0432 \\u043e\\u0431\\u043b\\u0430\\u0441\\u0442\\u0438 \\u044d\\u0441\\u0442\\u0435\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0439 \\u0441\\u0442\\u043e\\u043c\\u0430\\u0442\\u043e\\u043b\\u043e\\u0433\\u0438\\u0438\",\"\\u041c\\u0433\\u043d\\u043e\\u0432\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0438 \\u0432\\u043f\\u0435\\u0447\\u0430\\u0442\\u043b\\u044f\\u044e\\u0449\\u0438\\u0439 \\u044d\\u0441\\u0442\\u0435\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\"]}', '[{\"title\":{\"en\":\"The Ultimate Smile Transformation\",\"ar\":\"\\u0627\\u0644\\u062a\\u062d\\u0648\\u0644 \\u0627\\u0644\\u0646\\u0647\\u0627\\u0626\\u064a \\u0644\\u0627\\u0628\\u062a\\u0633\\u0627\\u0645\\u062a\\u0643\",\"fr\":\"La Transformation Ultime de Votre Sourire\",\"ru\":\"\\u041f\\u043e\\u043b\\u043d\\u043e\\u0435 \\u043f\\u0440\\u0435\\u043e\\u0431\\u0440\\u0430\\u0436\\u0435\\u043d\\u0438\\u0435 \\u0432\\u0430\\u0448\\u0435\\u0439 \\u0443\\u043b\\u044b\\u0431\\u043a\\u0438\"},\"subtitle\":{\"en\":\"Your Hollywood Smile Awaits in Istanbul\",\"ar\":\"\\u0627\\u0628\\u062a\\u0633\\u0627\\u0645\\u0629 \\u0647\\u0648\\u0644\\u064a\\u0648\\u062f \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643 \\u062a\\u0646\\u062a\\u0638\\u0631\\u0643 \\u0641\\u064a \\u0625\\u0633\\u0637\\u0646\\u0628\\u0648\\u0644\",\"fr\":\"Votre Hollywood Smile vous attend \\u00e0 Istanbul\",\"ru\":\"\\u0412\\u0430\\u0448\\u0430 \\u0433\\u043e\\u043b\\u043b\\u0438\\u0432\\u0443\\u0434\\u0441\\u043a\\u0430\\u044f \\u0443\\u043b\\u044b\\u0431\\u043a\\u0430 \\u0436\\u0434\\u0435\\u0442 \\u0432\\u0430\\u0441 \\u0432 \\u0421\\u0442\\u0430\\u043c\\u0431\\u0443\\u043b\\u0435\"},\"description\":{\"en\":\"Achieve the dazzling, symmetrical, and white smile of your dreams. Our custom-designed porcelain veneers and digital smile design technology create a perfect result that is tailored to your unique facial features. Experience world-class cosmetic dentistry at Gravity Clinic and step into a more confident you.\",\"ar\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0627\\u0628\\u062a\\u0633\\u0627\\u0645\\u0629 \\u0627\\u0644\\u0628\\u0631\\u0627\\u0642\\u0629 \\u0648\\u0627\\u0644\\u0645\\u062a\\u0646\\u0627\\u0638\\u0631\\u0629 \\u0648\\u0627\\u0644\\u0628\\u064a\\u0636\\u0627\\u0621 \\u0627\\u0644\\u062a\\u064a \\u062a\\u062d\\u0644\\u0645 \\u0628\\u0647\\u0627. \\u0642\\u0634\\u0648\\u0631 \\u0627\\u0644\\u0628\\u0648\\u0631\\u0633\\u0644\\u064a\\u0646 \\u0627\\u0644\\u0645\\u0635\\u0645\\u0645\\u0629 \\u062e\\u0635\\u064a\\u0635\\u0627\\u064b \\u0648\\u062a\\u0642\\u0646\\u064a\\u0629 \\u062a\\u0635\\u0645\\u064a\\u0645 \\u0627\\u0644\\u0627\\u0628\\u062a\\u0633\\u0627\\u0645\\u0629 \\u0627\\u0644\\u0631\\u0642\\u0645\\u064a\\u0629 \\u0644\\u062f\\u064a\\u0646\\u0627 \\u062a\\u062e\\u0644\\u0642 \\u0646\\u062a\\u064a\\u062c\\u0629 \\u0645\\u062b\\u0627\\u0644\\u064a\\u0629 \\u0645\\u0635\\u0645\\u0645\\u0629 \\u062e\\u0635\\u064a\\u0635\\u0627\\u064b \\u0644\\u0645\\u064a\\u0632\\u0627\\u062a \\u0648\\u062c\\u0647\\u0643 \\u0627\\u0644\\u0641\\u0631\\u064a\\u062f\\u0629. \\u062c\\u0631\\u0628 \\u0637\\u0628 \\u0627\\u0644\\u0623\\u0633\\u0646\\u0627\\u0646 \\u0627\\u0644\\u062a\\u062c\\u0645\\u064a\\u0644\\u064a \\u0639\\u0627\\u0644\\u0645\\u064a \\u0627\\u0644\\u0645\\u0633\\u062a\\u0648\\u0649 \\u0641\\u064a \\u0639\\u064a\\u0627\\u062f\\u0629 \\u062c\\u0631\\u0627\\u0641\\u064a\\u062a\\u064a \\u0648\\u0627\\u062e\\u0637\\u064f \\u0646\\u062d\\u0648 \\u0646\\u0633\\u062e\\u0629 \\u0623\\u0643\\u062b\\u0631 \\u062b\\u0642\\u0629 \\u0645\\u0646 \\u0646\\u0641\\u0633\\u0643.\",\"fr\":\"Obtenez le sourire \\u00e9clatant, sym\\u00e9trique et blanc de vos r\\u00eaves. Nos facettes en porcelaine con\\u00e7ues sur mesure et notre technologie de conception num\\u00e9rique du sourire cr\\u00e9ent un r\\u00e9sultat parfait, adapt\\u00e9 \\u00e0 vos traits de visage uniques. D\\u00e9couvrez la dentisterie esth\\u00e9tique de classe mondiale \\u00e0 la clinique Gravity et devenez plus confiant.\",\"ru\":\"\\u041e\\u0431\\u0440\\u0435\\u0442\\u0438\\u0442\\u0435 \\u043e\\u0441\\u043b\\u0435\\u043f\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u0443\\u044e, \\u0441\\u0438\\u043c\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u0443\\u044e \\u0438 \\u0431\\u0435\\u043b\\u043e\\u0441\\u043d\\u0435\\u0436\\u043d\\u0443\\u044e \\u0443\\u043b\\u044b\\u0431\\u043a\\u0443 \\u0441\\u0432\\u043e\\u0435\\u0439 \\u043c\\u0435\\u0447\\u0442\\u044b. \\u041d\\u0430\\u0448\\u0438 \\u0444\\u0430\\u0440\\u0444\\u043e\\u0440\\u043e\\u0432\\u044b\\u0435 \\u0432\\u0438\\u043d\\u0438\\u0440\\u044b \\u0438\\u043d\\u0434\\u0438\\u0432\\u0438\\u0434\\u0443\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430 \\u0438 \\u0442\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u044f \\u0446\\u0438\\u0444\\u0440\\u043e\\u0432\\u043e\\u0433\\u043e \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430 \\u0443\\u043b\\u044b\\u0431\\u043a\\u0438 \\u0441\\u043e\\u0437\\u0434\\u0430\\u044e\\u0442 \\u0438\\u0434\\u0435\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442, \\u0430\\u0434\\u0430\\u043f\\u0442\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 \\u043a \\u0432\\u0430\\u0448\\u0438\\u043c \\u0443\\u043d\\u0438\\u043a\\u0430\\u043b\\u044c\\u043d\\u044b\\u043c \\u0447\\u0435\\u0440\\u0442\\u0430\\u043c \\u043b\\u0438\\u0446\\u0430. \\u041e\\u0446\\u0435\\u043d\\u0438\\u0442\\u0435 \\u043a\\u043e\\u0441\\u043c\\u0435\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0443\\u044e \\u0441\\u0442\\u043e\\u043c\\u0430\\u0442\\u043e\\u043b\\u043e\\u0433\\u0438\\u044e \\u043c\\u0438\\u0440\\u043e\\u0432\\u043e\\u0433\\u043e \\u0443\\u0440\\u043e\\u0432\\u043d\\u044f \\u0432 \\u043a\\u043b\\u0438\\u043d\\u0438\\u043a\\u0435 Gravity \\u0438 \\u0441\\u0434\\u0435\\u043b\\u0430\\u0439\\u0442\\u0435 \\u0448\\u0430\\u0433 \\u043d\\u0430\\u0432\\u0441\\u0442\\u0440\\u0435\\u0447\\u0443 \\u0443\\u0432\\u0435\\u0440\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438 \\u0432 \\u0441\\u0435\\u0431\\u0435.\"},\"image\":\"https:\\/\\/gravity-clinic.com\\/storage\\/uploads\\/1775934923_Hollywood Smile.jpg\",\"media_id\":123},{\"title\":{\"en\":\"Superior Quality Materials\",\"ar\":\"\\u0645\\u0648\\u0627\\u062f \\u0630\\u0627\\u062a \\u062c\\u0648\\u062f\\u0629 \\u0641\\u0627\\u0626\\u0642\\u0629\",\"fr\":\"Mat\\u00e9riaux de Qualit\\u00e9 Sup\\u00e9rieure\",\"ru\":\"\\u041c\\u0430\\u0442\\u0435\\u0440\\u0438\\u0430\\u043b\\u044b \\u0432\\u044b\\u0441\\u0448\\u0435\\u0433\\u043e \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0430\"},\"subtitle\":{\"en\":\"Durable E-max and Zirconia Veneers\",\"ar\":\"\\u0642\\u0634\\u0648\\u0631 \\u0625\\u064a-\\u0645\\u0627\\u0643\\u0633 \\u0648\\u0627\\u0644\\u0632\\u0631\\u0643\\u0648\\u0646\\u064a\\u0627 \\u0627\\u0644\\u0645\\u062a\\u064a\\u0646\\u0629\",\"fr\":\"Facettes Durables en E-max et Zircone\",\"ru\":\"\\u0414\\u043e\\u043b\\u0433\\u043e\\u0432\\u0435\\u0447\\u043d\\u044b\\u0435 \\u0432\\u0438\\u043d\\u0438\\u0440\\u044b \\u0438\\u0437 E-max \\u0438 \\u0434\\u0438\\u043e\\u043a\\u0441\\u0438\\u0434\\u0430 \\u0446\\u0438\\u0440\\u043a\\u043e\\u043d\\u0438\\u044f\"},\"description\":{\"en\":\"We use only the finest E-max and Zirconia materials to craft your veneers. These premium ceramics offer natural translucency and exceptional strength, ensuring your Hollywood Smile remains bright and beautiful for years to come.\",\"ar\":\"\\u0646\\u062d\\u0646 \\u0646\\u0633\\u062a\\u062e\\u062f\\u0645 \\u0641\\u0642\\u0637 \\u0623\\u062c\\u0648\\u062f \\u0645\\u0648\\u0627\\u062f \\u0625\\u064a-\\u0645\\u0627\\u0643\\u0633 \\u0648\\u0627\\u0644\\u0632\\u0631\\u0643\\u0648\\u0646\\u064a\\u0627 \\u0644\\u0635\\u0646\\u0639 \\u0642\\u0634\\u0648\\u0631 \\u0623\\u0633\\u0646\\u0627\\u0646\\u0643. \\u062a\\u0648\\u0641\\u0631 \\u0647\\u0630\\u0647 \\u0627\\u0644\\u0633\\u064a\\u0631\\u0627\\u0645\\u064a\\u0643\\u064a\\u0627\\u062a \\u0627\\u0644\\u0645\\u0645\\u062a\\u0627\\u0632\\u0629 \\u0634\\u0641\\u0627\\u0641\\u064a\\u0629 \\u0637\\u0628\\u064a\\u0639\\u064a\\u0629 \\u0648\\u0642\\u0648\\u0629 \\u0627\\u0633\\u062a\\u062b\\u0646\\u0627\\u0626\\u064a\\u0629\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0636\\u0645\\u0646 \\u0628\\u0642\\u0627\\u0621 \\u0627\\u0628\\u062a\\u0633\\u0627\\u0645\\u0629 \\u0647\\u0648\\u0644\\u064a\\u0648\\u062f \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643 \\u0645\\u0634\\u0631\\u0642\\u0629 \\u0648\\u062c\\u0645\\u064a\\u0644\\u0629 \\u0644\\u0633\\u0646\\u0648\\u0627\\u062a \\u0642\\u0627\\u062f\\u0645\\u0629\",\"fr\":\"Nous utilisons uniquement les meilleurs mat\\u00e9riaux E-max et Zircone pour fabriquer vos facettes. Ces c\\u00e9ramiques de qualit\\u00e9 sup\\u00e9rieure offrent une translucidit\\u00e9 naturelle et une r\\u00e9sistance exceptionnelle, garantissant que votre Hollywood Smile reste \\u00e9clatant pour les ann\\u00e9es \\u00e0 venir.\",\"ru\":\"\\u041c\\u044b \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u0443\\u0435\\u043c \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043b\\u0443\\u0447\\u0448\\u0438\\u0435 \\u043c\\u0430\\u0442\\u0435\\u0440\\u0438\\u0430\\u043b\\u044b E-max \\u0438 \\u0434\\u0438\\u043e\\u043a\\u0441\\u0438\\u0434 \\u0446\\u0438\\u0440\\u043a\\u043e\\u043d\\u0438\\u044f \\u0434\\u043b\\u044f \\u0438\\u0437\\u0433\\u043e\\u0442\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f \\u0432\\u0430\\u0448\\u0438\\u0445 \\u0432\\u0438\\u043d\\u0438\\u0440\\u043e\\u0432. \\u042d\\u0442\\u0430 \\u043f\\u0440\\u0435\\u043c\\u0438\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f \\u043a\\u0435\\u0440\\u0430\\u043c\\u0438\\u043a\\u0430 \\u043e\\u0431\\u043b\\u0430\\u0434\\u0430\\u0435\\u0442 \\u0435\\u0441\\u0442\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e\\u0439 \\u043f\\u0440\\u043e\\u0437\\u0440\\u0430\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c\\u044e \\u0438 \\u0438\\u0441\\u043a\\u043b\\u044e\\u0447\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0439 \\u043f\\u0440\\u043e\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c\\u044e, \\u0433\\u0430\\u0440\\u0430\\u043d\\u0442\\u0438\\u0440\\u0443\\u044f, \\u0447\\u0442\\u043e \\u0432\\u0430\\u0448\\u0430 \\u0433\\u043e\\u043b\\u043b\\u0438\\u0432\\u0443\\u0434\\u0441\\u043a\\u0430\\u044f \\u0443\\u043b\\u044b\\u0431\\u043a\\u0430 \\u0431\\u0443\\u0434\\u0435\\u0442 \\u043e\\u0441\\u0442\\u0430\\u0432\\u0430\\u0442\\u044c\\u0441\\u044f \\u044f\\u0440\\u043a\\u043e\\u0439 \\u0438 \\u043a\\u0440\\u0430\\u0441\\u0438\\u0432\\u043e\\u0439 \\u0434\\u043e\\u043b\\u0433\\u0438\\u0435 \\u0433\\u043e\\u0434\\u044b.\"},\"image\":\"https:\\/\\/gravity-clinic.com\\/storage\\/uploads\\/1776157447_premium-e-max-veneers-hollywood-smile.jpg.png\",\"media_id\":134},{\"title\":{\"en\":\"Precision Digital Design\",\"ar\":\"\\u062a\\u0635\\u0645\\u064a\\u0645 \\u0631\\u0642\\u0645\\u064a \\u062f\\u0642\\u064a\\u0642\",\"fr\":\"Conception Num\\u00e9rique de Pr\\u00e9cision\",\"ru\":\"\\u0422\\u043e\\u0447\\u043d\\u044b\\u0439 \\u0446\\u0438\\u0444\\u0440\\u043e\\u0432\\u043e\\u0439 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\"},\"subtitle\":{\"en\":\"Preview Your Perfect Smile\",\"ar\":\"\\u0639\\u0627\\u064a\\u0646 \\u0627\\u0628\\u062a\\u0633\\u0627\\u0645\\u062a\\u0643 \\u0627\\u0644\\u0645\\u062b\\u0627\\u0644\\u064a\\u0629\",\"fr\":\"Pr\\u00e9visualisez Votre Sourire Parfait\",\"ru\":\"\\u041f\\u0440\\u0435\\u0434\\u0432\\u0430\\u0440\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u043f\\u0440\\u043e\\u0441\\u043c\\u043e\\u0442\\u0440 \\u0432\\u0430\\u0448\\u0435\\u0439 \\u0438\\u0434\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0443\\u043b\\u044b\\u0431\\u043a\\u0438\"},\"description\":{\"en\":\"Using advanced Digital Smile Design (DSD) technology, we plan your transformation with mathematical precision. You can see a 3D preview of your final result before we even begin, ensuring the shape and color perfectly match your facial features.\",\"ar\":\"\\u0628\\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u062a\\u0642\\u0646\\u064a\\u0629 \\u062a\\u0635\\u0645\\u064a\\u0645 \\u0627\\u0644\\u0627\\u0628\\u062a\\u0633\\u0627\\u0645\\u0629 \\u0627\\u0644\\u0631\\u0642\\u0645\\u064a\\u0629 (DSD) \\u0627\\u0644\\u0645\\u062a\\u0642\\u062f\\u0645\\u0629\\u060c \\u0646\\u062e\\u0637\\u0637 \\u0644\\u062a\\u062d\\u0648\\u0644\\u0643 \\u0628\\u062f\\u0642\\u0629 \\u0631\\u064a\\u0627\\u0636\\u064a\\u0629. \\u064a\\u0645\\u0643\\u0646\\u0643 \\u0631\\u0624\\u064a\\u0629 \\u0645\\u0639\\u0627\\u064a\\u0646\\u0629 \\u062b\\u0644\\u0627\\u062b\\u064a\\u0629 \\u0627\\u0644\\u0623\\u0628\\u0639\\u0627\\u062f \\u0644\\u0646\\u062a\\u064a\\u062c\\u062a\\u0643 \\u0627\\u0644\\u0646\\u0647\\u0627\\u0626\\u064a\\u0629 \\u0642\\u0628\\u0644 \\u0623\\u0646 \\u0646\\u0628\\u062f\\u0623\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0636\\u0645\\u0646 \\u062a\\u0648\\u0627\\u0641\\u0642 \\u0627\\u0644\\u0634\\u0643\\u0644 \\u0648\\u0627\\u0644\\u0644\\u0648\\u0646 \\u062a\\u0645\\u0627\\u0645\\u0627\\u064b \\u0645\\u0639 \\u0645\\u064a\\u0632\\u0627\\u062a \\u0648\\u062c\\u0647\\u0643.\",\"fr\":\"Gr\\u00e2ce \\u00e0 la technologie avanc\\u00e9e de Digital Smile Design (DSD), nous planifions votre transformation avec une pr\\u00e9cision math\\u00e9matique. Vous pouvez voir un aper\\u00e7u en 3D de votre r\\u00e9sultat final avant m\\u00eame de commencer, garantissant que la forme et la couleur correspondent parfaitement aux traits de votre visage.\",\"ru\":\"\\u0418\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u0443\\u044f \\u043f\\u0435\\u0440\\u0435\\u0434\\u043e\\u0432\\u0443\\u044e \\u0442\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u044e \\u0446\\u0438\\u0444\\u0440\\u043e\\u0432\\u043e\\u0433\\u043e \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430 \\u0443\\u043b\\u044b\\u0431\\u043a\\u0438 (DSD), \\u043c\\u044b \\u043f\\u043b\\u0430\\u043d\\u0438\\u0440\\u0443\\u0435\\u043c \\u0432\\u0430\\u0448\\u0435 \\u043f\\u0440\\u0435\\u043e\\u0431\\u0440\\u0430\\u0436\\u0435\\u043d\\u0438\\u0435 \\u0441 \\u043c\\u0430\\u0442\\u0435\\u043c\\u0430\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0439 \\u0442\\u043e\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c\\u044e. \\u0412\\u044b \\u0441\\u043c\\u043e\\u0436\\u0435\\u0442\\u0435 \\u0443\\u0432\\u0438\\u0434\\u0435\\u0442\\u044c 3D-\\u043c\\u043e\\u0434\\u0435\\u043b\\u044c \\u043a\\u043e\\u043d\\u0435\\u0447\\u043d\\u043e\\u0433\\u043e \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u0430 \\u0435\\u0449\\u0435 \\u0434\\u043e \\u043d\\u0430\\u0447\\u0430\\u043b\\u0430 \\u0440\\u0430\\u0431\\u043e\\u0442\\u044b, \\u0447\\u0442\\u043e \\u0433\\u0430\\u0440\\u0430\\u043d\\u0442\\u0438\\u0440\\u0443\\u0435\\u0442 \\u0438\\u0434\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e\\u0435 \\u0441\\u043e\\u043e\\u0442\\u0432\\u0435\\u0442\\u0441\\u0442\\u0432\\u0438\\u0435 \\u0444\\u043e\\u0440\\u043c\\u044b \\u0438 \\u0446\\u0432\\u0435\\u0442\\u0430 \\u0432\\u0430\\u0448\\u0438\\u043c \\u0447\\u0435\\u0440\\u0442\\u0430\\u043c \\u043b\\u0438\\u0446\\u0430.\"},\"image\":\"https:\\/\\/gravity-clinic.com\\/storage\\/uploads\\/1776157302_digital-smile-design-planning-istanbul.jpg\",\"media_id\":133}]', 'dental', 1, 1, '2026-04-05 20:03:24', '2026-04-14 09:04:12'),
(3, 'male-hair-transplant', '{\"en\":\"Male Hair Transplant\",\"ar\":\"\\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0634\\u0639\\u0631 \\u0644\\u0644\\u0631\\u062c\\u0627\\u0644\",\"fr\":\"Greffe de Cheveux Homme\",\"ru\":\"\\u041f\\u0435\\u0440\\u0435\\u0441\\u0430\\u0434\\u043a\\u0430 \\u0432\\u043e\\u043b\\u043e\\u0441 \\u0443 \\u043c\\u0443\\u0436\\u0447\\u0438\\u043d\"}', '{\"en\":\"Male Hair Transplant\",\"ar\":\"\\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0634\\u0639\\u0631 \\u0644\\u0644\\u0631\\u062c\\u0627\\u0644\",\"fr\":\"Greffe Homme\",\"ru\":\"\\u041c\\u0443\\u0436\\u0447\\u0438\\u043d\\u044b\"}', 61, 63, 62, '{\"en\":\"Regain your natural look and confidence with the latest male hair transplant techniques in Istanbul. Experience permanent results, maximum density, and expert medical care at competitive prices.\",\"ar\":\"\\u0627\\u0633\\u062a\\u0639\\u062f \\u0645\\u0638\\u0647\\u0631\\u0643 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0639\\u064a \\u0648\\u062b\\u0642\\u062a\\u0643 \\u0628\\u0646\\u0641\\u0633\\u0643 \\u0645\\u0639 \\u0623\\u062d\\u062f\\u062b \\u062a\\u0642\\u0646\\u064a\\u0627\\u062a \\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0634\\u0639\\u0631 \\u0644\\u0644\\u0631\\u062c\\u0627\\u0644 \\u0641\\u064a \\u0625\\u0633\\u0637\\u0646\\u0628\\u0648\\u0644. \\u0646\\u062a\\u0627\\u0626\\u062c \\u062f\\u0627\\u0626\\u0645\\u0629\\u060c \\u0643\\u062b\\u0627\\u0641\\u0629 \\u0645\\u062b\\u0627\\u0644\\u064a\\u0629\\u060c \\u0648\\u0631\\u0639\\u0627\\u064a\\u0629 \\u0637\\u0628\\u064a\\u0629 \\u0645\\u062a\\u0645\\u064a\\u0632\\u0629 \\u0628\\u0623\\u0633\\u0639\\u0627\\u0631 \\u062a\\u0646\\u0627\\u0641\\u0633\\u064a\\u0629.\",\"fr\":\"Retrouvez votre aspect naturel et votre confiance avec les derni\\u00e8res techniques de greffe de cheveux pour hommes \\u00e0 Istanbul. Profitez de r\\u00e9sultats permanents, d\'une densit\\u00e9 maximale et de soins experts \\u00e0 des tarifs comp\\u00e9titifs.\",\"ru\":\"\\u0412\\u0435\\u0440\\u043d\\u0438\\u0442\\u0435 \\u0441\\u0432\\u043e\\u0439 \\u0435\\u0441\\u0442\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0432\\u0438\\u0434 \\u0438 \\u0443\\u0432\\u0435\\u0440\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c \\u0441 \\u043f\\u043e\\u043c\\u043e\\u0449\\u044c\\u044e \\u043d\\u043e\\u0432\\u0435\\u0439\\u0448\\u0438\\u0445 \\u043c\\u0435\\u0442\\u043e\\u0434\\u043e\\u0432 \\u043f\\u0435\\u0440\\u0435\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0432\\u043e\\u043b\\u043e\\u0441 \\u0434\\u043b\\u044f \\u043c\\u0443\\u0436\\u0447\\u0438\\u043d \\u0432 \\u0421\\u0442\\u0430\\u043c\\u0431\\u0443\\u043b\\u0435. \\u041f\\u043e\\u0441\\u0442\\u043e\\u044f\\u043d\\u043d\\u044b\\u0439 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442, \\u043c\\u0430\\u043a\\u0441\\u0438\\u043c\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f \\u0433\\u0443\\u0441\\u0442\\u043e\\u0442\\u0430 \\u0438 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0442\\u043d\\u044b\\u0439 \\u0443\\u0445\\u043e\\u0434 \\u043f\\u043e \\u043a\\u043e\\u043d\\u043a\\u0443\\u0440\\u0435\\u043d\\u0442\\u043e\\u0441\\u043f\\u043e\\u0441\\u043e\\u0431\\u043d\\u044b\\u043c \\u0446\\u0435\\u043d\\u0430\\u043c.\"}', 98.00, '{\"en\":\"1 Day\",\"ar\":\"\\u064a\\u0648\\u0645\\u064a\\u0646 (\\u062c\\u0644\\u0633\\u0629 \\u0648\\u0627\\u062d\\u062f\\u0629)\",\"fr\":\"2 Jours (1 S\\u00e9ance)\",\"ru\":\"2 \\u0434\\u043d\\u044f (1 \\u0441\\u0435\\u0430\\u043d\\u0441)\"}', '{\"en\":[\"Advanced FUE & DHI Extraction Techniques\",\"Natural Hairline Design Tailored to Your Face\",\"Maximum Graft Density & Lifetime Results\",\"Specialized Medical Team with 15+ Years Experience\",\"Comprehensive Aftercare & Written Result Guarantee\"],\"ar\":[\"\\u0623\\u062d\\u062f\\u062b \\u062a\\u0642\\u0646\\u064a\\u0627\\u062a \\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0634\\u0639\\u0631 (FUE & DHI)\",\"\\u062a\\u0635\\u0645\\u064a\\u0645 \\u062e\\u0637 \\u0634\\u0639\\u0631 \\u0637\\u0628\\u064a\\u0639\\u064a \\u064a\\u062a\\u0646\\u0627\\u0633\\u0628 \\u0645\\u0639 \\u0645\\u0644\\u0627\\u0645\\u062d \\u0627\\u0644\\u0648\\u062c\\u0647\",\"\\u0643\\u062b\\u0627\\u0641\\u0629 \\u0642\\u0635\\u0648\\u0649 \\u0648\\u0646\\u062a\\u0627\\u0626\\u062c \\u062a\\u062f\\u0648\\u0645 \\u0645\\u062f\\u0649 \\u0627\\u0644\\u062d\\u064a\\u0627\\u0629\",\"\\u0641\\u0631\\u064a\\u0642 \\u0637\\u0628\\u064a \\u0645\\u062a\\u062e\\u0635\\u0635 \\u0628\\u062e\\u0628\\u0631\\u0629 \\u062a\\u0632\\u064a\\u062f \\u0639\\u0646 15 \\u0639\\u0627\\u0645\\u0627\\u064b\",\"\\u0631\\u0639\\u0627\\u064a\\u0629 \\u0634\\u0627\\u0645\\u0644\\u0629 \\u0645\\u0627 \\u0628\\u0639\\u062f \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0648\\u0636\\u0645\\u0627\\u0646 \\u0643\\u062a\\u0627\\u0628\\u064a \\u0644\\u0644\\u0646\\u062a\\u0627\\u0626\\u062c\"],\"fr\":[\"Techniques avanc\\u00e9es FUE et DHI Sapphire\",\"Conception d\'une ligne frontale naturelle et personnalis\\u00e9e\",\"Densit\\u00e9 maximale de greffons et r\\u00e9sultats \\u00e0 vie\",\"\\u00c9quipe m\\u00e9dicale sp\\u00e9cialis\\u00e9e avec plus de 15 ans d\'exp\\u00e9rience\",\"Suivi post-op\\u00e9ratoire complet et garantie de r\\u00e9sultat \\u00e9crite\"],\"ru\":[\"\\u041f\\u0435\\u0440\\u0435\\u0434\\u043e\\u0432\\u044b\\u0435 \\u043c\\u0435\\u0442\\u043e\\u0434\\u044b \\u044d\\u043a\\u0441\\u0442\\u0440\\u0430\\u043a\\u0446\\u0438\\u0438 FUE \\u0438 DHI Sapphire\",\"\\u0414\\u0438\\u0437\\u0430\\u0439\\u043d \\u0435\\u0441\\u0442\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e\\u0439 \\u043b\\u0438\\u043d\\u0438\\u0438 \\u0440\\u043e\\u0441\\u0442\\u0430 \\u0432\\u043e\\u043b\\u043e\\u0441 \\u043f\\u043e\\u0434 \\u0432\\u0430\\u0448 \\u0442\\u0438\\u043f \\u043b\\u0438\\u0446\\u0430\",\"\\u041c\\u0430\\u043a\\u0441\\u0438\\u043c\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f \\u0433\\u0443\\u0441\\u0442\\u043e\\u0442\\u0430 \\u0433\\u0440\\u0430\\u0444\\u0442\\u043e\\u0432 \\u0438 \\u043f\\u043e\\u0436\\u0438\\u0437\\u043d\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\",\"\\u0421\\u043f\\u0435\\u0446\\u0438\\u0430\\u043b\\u0438\\u0437\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u0430\\u044f \\u043c\\u0435\\u0434\\u0438\\u0446\\u0438\\u043d\\u0441\\u043a\\u0430\\u044f \\u043a\\u043e\\u043c\\u0430\\u043d\\u0434\\u0430 \\u0441 \\u043e\\u043f\\u044b\\u0442\\u043e\\u043c 15+ \\u043b\\u0435\\u0442\",\"\\u041a\\u043e\\u043c\\u043f\\u043b\\u0435\\u043a\\u0441\\u043d\\u044b\\u0439 \\u043f\\u043e\\u0441\\u043b\\u0435\\u043e\\u043f\\u0435\\u0440\\u0430\\u0446\\u0438\\u043e\\u043d\\u043d\\u044b\\u0439 \\u0443\\u0445\\u043e\\u0434 \\u0438 \\u043f\\u0438\\u0441\\u044c\\u043c\\u0435\\u043d\\u043d\\u0430\\u044f \\u0433\\u0430\\u0440\\u0430\\u043d\\u0442\\u0438\\u044f\"]}', '[{\"title\":{\"en\":\"Restore Your Confidence, Redefine Your Look\",\"ar\":\"\\u0627\\u0633\\u062a\\u0639\\u062f \\u062b\\u0642\\u062a\\u0643 \\u0628\\u0646\\u0641\\u0633\\u0643\\u060c \\u0648\\u0623\\u0639\\u062f \\u062a\\u0639\\u0631\\u064a\\u0641 \\u0645\\u0638\\u0647\\u0631\\u0643\",\"fr\":\"Restaurez Votre Confiance, Red\\u00e9finissez Votre Look\",\"ru\":\"\\u0412\\u0435\\u0440\\u043d\\u0438\\u0442\\u0435 \\u0443\\u0432\\u0435\\u0440\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c, \\u0438\\u0437\\u043c\\u0435\\u043d\\u0438\\u0442\\u0435 \\u0441\\u0432\\u043e\\u0439 \\u043e\\u0431\\u0440\\u0430\\u0437\"},\"subtitle\":{\"en\":\"Elite Hair Restoration for Men in Istanbul\",\"ar\":\"\\u0627\\u0633\\u062a\\u0639\\u0627\\u062f\\u0629 \\u0627\\u0644\\u0634\\u0639\\u0631 \\u0644\\u0644\\u0631\\u062c\\u0627\\u0644 \\u0645\\u0646 \\u0627\\u0644\\u0646\\u062e\\u0628\\u0629 \\u0641\\u064a \\u0625\\u0633\\u0637\\u0646\\u0628\\u0648\\u0644\",\"fr\":\"Restauration Capillaire d\'\\u00c9lite pour Hommes \\u00e0 Istanbul\",\"ru\":\"\\u042d\\u043b\\u0438\\u0442\\u043d\\u043e\\u0435 \\u0432\\u043e\\u0441\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u0435 \\u0432\\u043e\\u043b\\u043e\\u0441 \\u0434\\u043b\\u044f \\u043c\\u0443\\u0436\\u0447\\u0438\\u043d \\u0432 \\u0421\\u0442\\u0430\\u043c\\u0431\\u0443\\u043b\\u0435\"},\"description\":{\"en\":\"Regain your natural-looking, dense hair with our advanced FUE and DHI hair transplant techniques. Our world-renowned specialists design a personalized hairline tailored to your facial features, ensuring a painless procedure and high-success results. Experience the Gravity Clinic difference in our state-of-the-art facility.\",\"ar\":\"\\u0627\\u0633\\u062a\\u0639\\u062f \\u0634\\u0639\\u0631\\u0643 \\u0627\\u0644\\u0643\\u062b\\u064a\\u0641 \\u0630\\u0648 \\u0627\\u0644\\u0645\\u0638\\u0647\\u0631 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0639\\u064a \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u062a\\u0642\\u0646\\u064a\\u0627\\u062a \\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0634\\u0639\\u0631 \\u0627\\u0644\\u0645\\u062a\\u0642\\u062f\\u0645\\u0629 FUE \\u0648 DHI. \\u064a\\u0635\\u0645\\u0645 \\u0623\\u062e\\u0635\\u0627\\u0626\\u064a\\u0648\\u0646\\u0627 \\u0627\\u0644\\u0645\\u0634\\u0647\\u0648\\u0631\\u0648\\u0646 \\u0639\\u0627\\u0644\\u0645\\u064a\\u0627\\u064b \\u062e\\u0637 \\u0634\\u0639\\u0631 \\u0645\\u062e\\u0635\\u0635\\u0627\\u064b \\u064a\\u062a\\u0646\\u0627\\u0633\\u0628 \\u0645\\u0639 \\u0645\\u064a\\u0632\\u0627\\u062a \\u0648\\u062c\\u0647\\u0643\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0636\\u0645\\u0646 \\u0625\\u062c\\u0631\\u0627\\u0621\\u064b \\u063a\\u064a\\u0631 \\u0645\\u0624\\u0644\\u0645 \\u0648\\u0646\\u062a\\u0627\\u0626\\u062c \\u0639\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0646\\u062c\\u0627\\u062d. \\u062c\\u0631\\u0628 \\u0641\\u0631\\u0642 \\u0639\\u064a\\u0627\\u062f\\u0629 \\u062c\\u0631\\u0627\\u0641\\u064a\\u062a\\u064a \\u0641\\u064a \\u0645\\u0646\\u0634\\u0623\\u062a\\u0646\\u0627 \\u0627\\u0644\\u0645\\u062a\\u0637\\u0648\\u0631\\u0629.\",\"fr\":\"Retrouvez vos cheveux denses et d\'aspect naturel gr\\u00e2ce \\u00e0 nos techniques avanc\\u00e9es de greffe de cheveux FUE et DHI. Nos sp\\u00e9cialistes de renomm\\u00e9e mondiale con\\u00e7oivent une ligne frontale personnalis\\u00e9e, adapt\\u00e9e \\u00e0 vos traits de visage, garantissant une proc\\u00e9dure sans douleur et des r\\u00e9sultats probants. D\\u00e9couvrez la diff\\u00e9rence Gravity Clinic dans notre \\u00e9tablissement de pointe.\",\"ru\":\"\\u0412\\u0435\\u0440\\u043d\\u0438\\u0442\\u0435 \\u0441\\u0432\\u043e\\u0438 \\u0433\\u0443\\u0441\\u0442\\u044b\\u0435 \\u0432\\u043e\\u043b\\u043e\\u0441\\u044b \\u0441 \\u0435\\u0441\\u0442\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u043c \\u0432\\u0438\\u0434\\u043e\\u043c \\u0431\\u043b\\u0430\\u0433\\u043e\\u0434\\u0430\\u0440\\u044f \\u043d\\u0430\\u0448\\u0438\\u043c \\u043f\\u0435\\u0440\\u0435\\u0434\\u043e\\u0432\\u044b\\u043c \\u043c\\u0435\\u0442\\u043e\\u0434\\u0430\\u043c \\u043f\\u0435\\u0440\\u0435\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0432\\u043e\\u043b\\u043e\\u0441 FUE \\u0438 DHI. \\u041d\\u0430\\u0448\\u0438 \\u0432\\u0441\\u0435\\u043c\\u0438\\u0440\\u043d\\u043e \\u0438\\u0437\\u0432\\u0435\\u0441\\u0442\\u043d\\u044b\\u0435 \\u0441\\u043f\\u0435\\u0446\\u0438\\u0430\\u043b\\u0438\\u0441\\u0442\\u044b \\u0440\\u0430\\u0437\\u0440\\u0430\\u0431\\u0430\\u0442\\u044b\\u0432\\u0430\\u044e\\u0442 \\u0438\\u043d\\u0434\\u0438\\u0432\\u0438\\u0434\\u0443\\u0430\\u043b\\u044c\\u043d\\u0443\\u044e \\u043b\\u0438\\u043d\\u0438\\u044e \\u0440\\u043e\\u0441\\u0442\\u0430 \\u0432\\u043e\\u043b\\u043e\\u0441, \\u0430\\u0434\\u0430\\u043f\\u0442\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u0443\\u044e \\u043a \\u0432\\u0430\\u0448\\u0438\\u043c \\u0447\\u0435\\u0440\\u0442\\u0430\\u043c \\u043b\\u0438\\u0446\\u0430, \\u0433\\u0430\\u0440\\u0430\\u043d\\u0442\\u0438\\u0440\\u0443\\u044f \\u0431\\u0435\\u0437\\u0431\\u043e\\u043b\\u0435\\u0437\\u043d\\u0435\\u043d\\u043d\\u0443\\u044e \\u043f\\u0440\\u043e\\u0446\\u0435\\u0434\\u0443\\u0440\\u0443 \\u0438 \\u0432\\u044b\\u0441\\u043e\\u043a\\u0438\\u0435 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u044b. \\u041e\\u0446\\u0435\\u043d\\u0438\\u0442\\u0435 \\u0440\\u0430\\u0437\\u043d\\u0438\\u0446\\u0443 Gravity Clinic \\u0432 \\u043d\\u0430\\u0448\\u0435\\u043c \\u0441\\u043e\\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u043e\\u043c \\u0443\\u0447\\u0440\\u0435\\u0436\\u0434\\u0435\\u043d\\u0438\\u0438.\"},\"image\":\"https:\\/\\/gravity-clinic.com\\/storage\\/uploads\\/1775935062_Male Hair Transplant.jpg\",\"media_id\":124},{\"title\":{\"en\":\"Cutting-Edge Hair Restoration\",\"ar\":\"\\u0623\\u062d\\u062f\\u062b \\u062a\\u0642\\u0646\\u064a\\u0627\\u062a \\u0627\\u0633\\u062a\\u0639\\u0627\\u062f\\u0629 \\u0627\\u0644\\u0634\\u0639\\u0631\",\"fr\":\"Restauration Capillaire de Pointe\",\"ru\":\"\\u041f\\u0435\\u0440\\u0435\\u0434\\u043e\\u0432\\u043e\\u0435 \\u0432\\u043e\\u0441\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u0435 \\u0432\\u043e\\u043b\\u043e\\u0441\"},\"subtitle\":{\"en\":\"Maximum Density with FUE and DHI\",\"ar\":\"\\u0623\\u0642\\u0635\\u0649 \\u0643\\u062b\\u0627\\u0641\\u0629 \\u0645\\u0639 \\u062a\\u0642\\u0646\\u064a\\u0627\\u062a FUE \\u0648 DHI\",\"fr\":\"Densit\\u00e9 Maximale avec FUE et DHI\",\"ru\":\"\\u041c\\u0430\\u043a\\u0441\\u0438\\u043c\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f \\u0433\\u0443\\u0441\\u0442\\u043e\\u0442\\u0430 \\u043c\\u0435\\u0442\\u043e\\u0434\\u0430\\u043c\\u0438 FUE \\u0438 DHI\"},\"description\":{\"en\":\"We utilize the latest FUE (Follicular Unit Extraction) and DHI (Direct Hair Implantation) methods to ensure natural-looking results with maximum density. These minimally invasive techniques allow for faster recovery and precise placement of each follicle to match your natural hair growth pattern.\",\"ar\":\"\\u0646\\u062d\\u0646 \\u0646\\u0633\\u062a\\u062e\\u062f\\u0645 \\u0623\\u062d\\u062f\\u062b \\u0637\\u0631\\u0642 FUE (\\u0627\\u0642\\u062a\\u0637\\u0627\\u0641 \\u0648\\u062d\\u062f\\u0629 \\u0627\\u0644\\u0628\\u0635\\u064a\\u0644\\u0629) \\u0648 DHI (\\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0634\\u0639\\u0631 \\u0627\\u0644\\u0645\\u0628\\u0627\\u0634\\u0631\\u0629) \\u0644\\u0636\\u0645\\u0627\\u0646 \\u0646\\u062a\\u0627\\u0626\\u062c \\u0630\\u0627\\u062a \\u0645\\u0638\\u0647\\u0631 \\u0637\\u0628\\u064a\\u0639\\u064a \\u0648\\u0623\\u0642\\u0635\\u0649 \\u0643\\u062b\\u0627\\u0641\\u0629. \\u062a\\u0633\\u0645\\u062d \\u0647\\u0630\\u0647 \\u0627\\u0644\\u062a\\u0642\\u0646\\u064a\\u0627\\u062a \\u0637\\u0641\\u064a\\u0641\\u0629 \\u0627\\u0644\\u062a\\u0648\\u063a\\u0644 \\u0628\\u0641\\u062a\\u0631\\u0629 \\u062a\\u0639\\u0627\\u0641\\u064a \\u0623\\u0633\\u0631\\u0639 \\u0648\\u0648\\u0636\\u0639 \\u062f\\u0642\\u064a\\u0642 \\u0644\\u0643\\u0644 \\u0628\\u0635\\u064a\\u0644\\u0629 \\u0644\\u062a\\u0646\\u0627\\u0633\\u0628 \\u0646\\u0645\\u0637 \\u0646\\u0645\\u0648 \\u0634\\u0639\\u0631\\u0643 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0639\\u064a.\",\"fr\":\"Nous utilisons les derni\\u00e8res m\\u00e9thodes FUE (Follicular Unit Extraction) et DHI (Direct Hair Implantation) pour garantir des r\\u00e9sultats naturels avec une densit\\u00e9 maximale. Ces techniques permettent une r\\u00e9cup\\u00e9ration plus rapide et une implantation pr\\u00e9cise de chaque follicule.\",\"ru\":\"\\u041c\\u044b \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u0443\\u0435\\u043c \\u043d\\u043e\\u0432\\u0435\\u0439\\u0448\\u0438\\u0435 \\u043c\\u0435\\u0442\\u043e\\u0434\\u044b FUE \\u0438 DHI \\u0434\\u043b\\u044f \\u043e\\u0431\\u0435\\u0441\\u043f\\u0435\\u0447\\u0435\\u043d\\u0438\\u044f \\u0435\\u0441\\u0442\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0445 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u043e\\u0432 \\u0438 \\u043c\\u0430\\u043a\\u0441\\u0438\\u043c\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0433\\u0443\\u0441\\u0442\\u043e\\u0442\\u044b. \\u042d\\u0442\\u0438 \\u043c\\u0430\\u043b\\u043e\\u0438\\u043dv\\u0430\\u0437\\u0438\\u0432\\u043d\\u044b\\u0435 \\u0442\\u0435\\u0445\\u043d\\u0438\\u043a\\u0438 \\u043f\\u043e\\u0437\\u0432\\u043e\\u043b\\u044f\\u044e\\u0442 \\u0441\\u043e\\u043a\\u0440\\u0430\\u0442\\u0438\\u0442\\u044c \\u0432\\u0440\\u0435\\u043c\\u044f \\u0432\\u043e\\u0441\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f \\u0438 \\u0442\\u043e\\u0447\\u043d\\u043e \\u0438\\u043c\\u0438\\u0442\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u0435\\u0441\\u0442\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0440\\u043e\\u0441\\u0442 \\u0432\\u043e\\u043b\\u043e\\u0441.\"},\"image\":\"https:\\/\\/gravity-clinic.com\\/storage\\/uploads\\/1776157803_advanced-dhi-hair-transplant-technique-istanbul.jpg\",\"media_id\":135},{\"title\":{\"en\":\"A Seamless VIP Experience\",\"ar\":\"\\u062a\\u062c\\u0631\\u0628\\u0629 VIP \\u0633\\u0644\\u0633\\u0629\",\"fr\":\"Une Exp\\u00e9rience VIP Sans Faille\",\"ru\":\"\\u0411\\u0435\\u0437\\u0443\\u043f\\u0440\\u0435\\u0447\\u043d\\u044b\\u0439 VIP-\\u0441\\u0435\\u0440\\u0432\\u0438\\u0441\"},\"subtitle\":{\"en\":\"Premium Support from Arrival to Recovery\",\"ar\":\"\\u062f\\u0639\\u0645 \\u0645\\u062a\\u0645\\u064a\\u0632 \\u0645\\u0646 \\u0627\\u0644\\u0648\\u0635\\u0648\\u0644 \\u0648\\u062d\\u062a\\u0649 \\u0627\\u0644\\u062a\\u0639\\u0627\\u0641\\u064a\",\"fr\":\"Un Soutien Premium de l\'Arriv\\u00e9e \\u00e0 la R\\u00e9cup\\u00e9ration\",\"ru\":\"\\u041f\\u0440\\u0435\\u043c\\u0438\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f \\u043f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u043a\\u0430 \\u043e\\u0442 \\u043f\\u0440\\u0438\\u043b\\u0435\\u0442\\u0430 \\u0434\\u043e \\u0432\\u043e\\u0441\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f\"},\"description\":{\"en\":\"Your journey to a full head of hair includes more than just the procedure. At Gravity Clinic, we provide 5-star hotel accommodation, VIP transfers, and a comprehensive aftercare package. Our team follows up with you throughout the healing process to ensure lifelong success and satisfaction.\",\"ar\":\"\\u0631\\u062d\\u0644\\u062a\\u0643 \\u0644\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0634\\u0639\\u0631 \\u0643\\u0627\\u0645\\u0644 \\u062a\\u0634\\u0645\\u0644 \\u0623\\u0643\\u062b\\u0631 \\u0645\\u0646 \\u0645\\u062c\\u0631\\u062f \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629. \\u0641\\u064a \\u0639\\u064a\\u0627\\u062f\\u0629 \\u062c\\u0631\\u0627\\u0641\\u064a\\u062a\\u064a\\u060c \\u0646\\u0648\\u0641\\u0631 \\u0625\\u0642\\u0627\\u0645\\u0629 \\u0641\\u064a \\u0641\\u0646\\u0627\\u062f\\u0642 5 \\u0646\\u062c\\u0648\\u0645\\u060c \\u0648\\u062a\\u0646\\u0642\\u0651\\u0644\\u0627\\u062a VIP\\u060c \\u0648\\u062d\\u0632\\u0645\\u0629 \\u0631\\u0639\\u0627\\u064a\\u0629 \\u0644\\u0627\\u062d\\u0642\\u0629 \\u0634\\u0627\\u0645\\u0644\\u0629. \\u064a\\u062a\\u0627\\u0628\\u0639 \\u0641\\u0631\\u064a\\u0642\\u0646\\u0627 \\u0645\\u0639\\u0643 \\u0637\\u0648\\u0627\\u0644 \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0634\\u0641\\u0627\\u0621 \\u0644\\u0636\\u0645\\u0627\\u0646 \\u0627\\u0644\\u0646\\u062c\\u0627\\u062d \\u0648\\u0627\\u0644\\u0631\\u0636\\u0627 \\u0645\\u062f\\u0649 \\u0627\\u0644\\u062d\\u064a\\u0627\\u0629\",\"fr\":\"Votre parcours comprend plus que la proc\\u00e9dure. \\u00c0 la Gravity Clinic, nous proposons un h\\u00e9bergement 5 \\u00e9toiles, des transferts VIP et un suivi complet pour garantir un succ\\u00e8s et une satisfaction \\u00e0 vie.\",\"ru\":\"\\u0412\\u0430\\u0448\\u0435 \\u043f\\u0440\\u0435\\u043e\\u0431\\u0440\\u0430\\u0436\\u0435\\u043d\\u0438\\u0435 \\u0432\\u043a\\u043b\\u044e\\u0447\\u0430\\u0435\\u0442 \\u0432 \\u0441\\u0435\\u0431\\u044f \\u0433\\u043e\\u0440\\u0430\\u0437\\u0434\\u043e \\u0431\\u043e\\u043b\\u044c\\u0448\\u0435, \\u0447\\u0435\\u043c \\u043f\\u0440\\u043e\\u0441\\u0442\\u043e \\u043f\\