23\\u0646 \\u0627\\u0644\\u062e\\u0635\\u0648\\u0635\\u064a\\u0629 \\u0623\\u0645\\u0631 \\u0623\\u0633\\u0627\\u0633\\u064a. \\u062a\\u062a\\u064a\\u062d \\u0644\\u0646\\u0627 \\u062a\\u0642\\u0646\\u064a\\u0629 DHI \\u0627\\u0644\\u0645\\u062a\\u062e\\u0635\\u0635\\u0629 \\\"\\u0628\\u062f\\u0648\\u0646 \\u062d\\u0644\\u0627\\u0642\\u0629\\\" \\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0634\\u0639\\u0631 \\u062f\\u0648\\u0646 \\u0642\\u0635 \\u0634\\u0639\\u0631\\u0643 \\u0627\\u0644\\u0637\\u0648\\u064a\\u0644 \\u0627\\u0644\\u062d\\u0627\\u0644\\u064a. \\u064a\\u0636\\u0645\\u0646 \\u0630\\u0644\\u0643 \\u0628\\u0642\\u0627\\u0621 \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0629 \\u0633\\u0631\\u064a\\u0629 \\u062a\\u0645\\u0627\\u0645\\u0627\\u064b\\u060c \\u0645\\u0645\\u0627 \\u064a\\u0633\\u0645\\u062d \\u0644\\u0643\\u0650 \\u0628\\u0627\\u0644\\u0639\\u0648\\u062f\\u0629 \\u0625\\u0644\\u0649 \\u062d\\u064a\\u0627\\u062a\\u0643 \\u0627\\u0644\\u0627\\u062c\\u062a\\u0645\\u0627\\u0639\\u064a\\u0629 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0641\\u0648\\u0631 \\u0628\\u0643\\u062b\\u0627\\u0641\\u0629 \\u0630\\u0627\\u062a \\u0645\\u0638\\u0647\\u0631 \\u0637\\u0628\\u064a\\u0639\\u064a.\",\"fr\":\"Nous comprenons que la confidentialit\\u00e9 est essentielle. Notre technique DHI sp\\u00e9cialis\\u00e9e \\\"Sans Rasage\\\" nous permet de transplanter des cheveux sans couper vos cheveux longs existants. Cela garantit que la proc\\u00e9dure reste totalement discr\\u00e8te, vous permettant de reprendre votre vie sociale presque imm\\u00e9diatement.\",\"ru\":\"\\u041c\\u044b \\u043f\\u043e\\u043d\\u0438\\u043c\\u0430\\u0435\\u043c, \\u043a\\u0430\\u043a \\u0432\\u0430\\u0436\\u043d\\u0430 \\u043a\\u043e\\u043d\\u0444\\u0438\\u0434\\u0435\\u043d\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u044c. \\u041d\\u0430\\u0448\\u0430 \\u0441\\u043f\\u0435\\u0446\\u0438\\u0430\\u043b\\u0438\\u0437\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u0430\\u044f \\u0442\\u0435\\u0445\\u043d\\u0438\\u043a\\u0430 DHI \\u00ab\\u0431\\u0435\\u0437 \\u0431\\u0440\\u0438\\u0442\\u044c\\u044f\\u00bb \\u043f\\u043e\\u0437\\u0432\\u043e\\u043b\\u044f\\u0435\\u0442 \\u043f\\u0435\\u0440\\u0435\\u0441\\u0430\\u0436\\u0438\\u0432\\u0430\\u0442\\u044c \\u0432\\u043e\\u043b\\u043e\\u0441\\u044b, \\u043d\\u0435 \\u0441\\u043e\\u0441\\u0442\\u0440\\u0438\\u0433\\u0430\\u044f \\u0432\\u0430\\u0448\\u0438 \\u0441\\u0443\\u0449\\u0435\\u0441\\u0442\\u0432\\u0443\\u044e\\u0449\\u0438\\u0435 \\u0434\\u043b\\u0438\\u043d\\u043d\\u044b\\u0435 \\u0432\\u043e\\u043b\\u043e\\u0441\\u044b. \\u042d\\u0442\\u043e \\u0434\\u0435\\u043b\\u0430\\u0435\\u0442 \\u043f\\u0440\\u043e\\u0446\\u0435\\u0434\\u0443\\u0440\\u0443 \\u0430\\u0431\\u0441\\u043e\\u043b\\u044e\\u0442\\u043d\\u043e \\u043d\\u0435\\u0437\\u0430\\u043c\\u0435\\u0442\\u043d\\u043e\\u0439, \\u043f\\u043e\\u0437\\u0432\\u043e\\u043b\\u044f\\u044f \\u0432\\u0430\\u043c \\u0432\\u0435\\u0440\\u043d\\u0443\\u0442\\u044c\\u0441\\u044f \\u043a \\u043f\\u0440\\u0438\\u0432\\u044b\\u0447\\u043d\\u043e\\u0439 \\u0436\\u0438\\u0437\\u043d\\u0438 \\u043f\\u0440\\u0430\\u043a\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438 \\u0441\\u0440\\u0430\\u0437\\u0443.\"},\"image\":\"https:\\/\\/gravity-clinic.com\\/storage\\/uploads\\/1776158498_non-shaven-female-hair-transplant-istanbul.jpg\",\"media_id\":137},{\"title\":{\"en\":\"The Art of Feminine Restoration\",\"ar\":\"\\u0641\\u0646 \\u0627\\u0633\\u062a\\u0639\\u0627\\u062f\\u0629 \\u0627\\u0644\\u0623\\u0646\\u0648\\u062b\\u0629\",\"fr\":\"L\'Art de la Restauration F\\u00e9minine\",\"ru\":\"\\u0418\\u0441\\u043a\\u0443\\u0441\\u0441\\u0442\\u0432\\u043e \\u0436\\u0435\\u043d\\u0441\\u043a\\u043e\\u0433\\u043e \\u0432\\u043e\\u0441\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f\"},\"subtitle\":{\"en\":\"Soft, Natural Hairline Mapping\",\"ar\":\"\\u0631\\u0633\\u0645 \\u062e\\u0637 \\u0634\\u0639\\u0631 \\u0646\\u0627\\u0639\\u0645 \\u0648\\u0637\\u0628\\u064a\\u0639\\u064a\",\"fr\":\"Trac\\u00e9 d\'une Ligne Capillaire Douce et Naturelle\",\"ru\":\"\\u041c\\u044f\\u0433\\u043a\\u0438\\u0439 \\u0438 \\u0435\\u0441\\u0442\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u043b\\u0438\\u043d\\u0438\\u0438 \\u0440\\u043e\\u0441\\u0442\\u0430 \\u0432\\u043e\\u043b\\u043e\\u0441\"},\"description\":{\"en\":\"A feminine hairline requires a different artistic approach than a male one. Our experts focus on soft, oval-shaped designs that frame your face perfectly. By meticulously placing follicles at the correct angle and direction, we create a soft transition that is indistinguishable from your natural hair.\",\"ar\":\"\\u064a\\u062a\\u0637\\u0644\\u0628 \\u062e\\u0637 \\u0627\\u0644\\u0634\\u0639\\u0631 \\u0627\\u0644\\u0623\\u0646\\u062b\\u0648\\u064a \\u0646\\u0647\\u062c\\u0627\\u064b \\u0641\\u0646\\u064a\\u0627\\u064b \\u0645\\u062e\\u062a\\u0644\\u0641\\u0627\\u064b \\u0639\\u0646 \\u062e\\u0637 \\u0627\\u0644\\u0634\\u0639\\u0631 \\u0627\\u0644\\u0630\\u0643\\u0648\\u0631\\u064a. \\u064a\\u0631\\u0643\\u0632 \\u062e\\u0628\\u0631\\u0627\\u0624\\u0646\\u0627 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u062a\\u0635\\u0627\\u0645\\u064a\\u0645 \\u0627\\u0644\\u0646\\u0627\\u0639\\u0645\\u0629 \\u0648\\u0627\\u0644\\u0628\\u064a\\u0636\\u0627\\u0648\\u064a\\u0629 \\u0627\\u0644\\u062a\\u064a \\u062a\\u0624\\u0637\\u0631 \\u0648\\u062c\\u0647\\u0643\\u0650 \\u0628\\u0634\\u0643\\u0644 \\u0645\\u062b\\u0627\\u0644\\u064a. \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0648\\u0636\\u0639 \\u0627\\u0644\\u0628\\u0635\\u064a\\u0644\\u0627\\u062a \\u0628\\u062f\\u0642\\u0629 \\u0628\\u0627\\u0644\\u0632\\u0627\\u0648\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0627\\u062a\\u062c\\u0627\\u0647 \\u0627\\u0644\\u0635\\u062d\\u064a\\u062d\\u064a\\u0646\\u060c \\u0646\\u062e\\u0644\\u0642 \\u0627\\u0646\\u062a\\u0642\\u0627\\u0644\\u0627\\u064b \\u0646\\u0627\\u0639\\u0645\\u0627\\u064b \\u0644\\u0627 \\u064a\\u0645\\u0643\\u0646 \\u062a\\u0645\\u064a\\u064a\\u0632\\u0647 \\u0639\\u0646 \\u0634\\u0639\\u0631\\u0643\\u0650 \\u0627\\u0644\\u0637\\u0628\\u064a\\u0639\\u064a.\",\"fr\":\"Une ligne capillaire f\\u00e9minine n\\u00e9cessite une approche artistique diff\\u00e9rente. Nos experts se concentrent sur des designs doux et ovales qui encadrent parfaitement votre visage. En pla\\u00e7ant m\\u00e9ticuleusement les follicules selon l\'angle correct, nous cr\\u00e9ons une transition invisible.\",\"ru\":\"\\u0416\\u0435\\u043d\\u0441\\u043a\\u0430\\u044f \\u043b\\u0438\\u043d\\u0438\\u044f \\u0440\\u043e\\u0441\\u0442\\u0430 \\u0432\\u043e\\u043b\\u043e\\u0441 \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0438\\u043d\\u043e\\u0433\\u043e \\u0445\\u0443\\u0434\\u043e\\u0436\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e\\u0433\\u043e \\u043f\\u043e\\u0434\\u0445\\u043e\\u0434\\u0430. \\u041d\\u0430\\u0448\\u0438 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0442\\u044b \\u0441\\u043e\\u0437\\u0434\\u0430\\u044e\\u0442 \\u043c\\u044f\\u0433\\u043a\\u0438\\u0435 \\u043e\\u0432\\u0430\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0444\\u043e\\u0440\\u043c\\u044b, \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0435 \\u0438\\u0434\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e \\u043e\\u0431\\u0440\\u0430\\u043c\\u043b\\u044f\\u044e\\u0442 \\u043b\\u0438\\u0446\\u043e. \\u0422\\u0449\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e \\u0440\\u0430\\u0441\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u044f\\u044f \\u0444\\u043e\\u043b\\u043b\\u0438\\u043a\\u0443\\u043b\\u044b \\u043f\\u043e\\u0434 \\u043d\\u0443\\u0436\\u043d\\u044b\\u043c \\u0443\\u0433\\u043b\\u043e\\u043c, \\u043c\\u044b \\u0434\\u043e\\u0431\\u0438\\u0432\\u0430\\u0435\\u043c\\u0441\\u044f \\u043f\\u043b\\u0430\\u0432\\u043d\\u043e\\u0433\\u043e \\u043f\\u0435\\u0440\\u0435\\u0445\\u043e\\u0434\\u0430, \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0439 \\u043d\\u0435\\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u043e \\u043e\\u0442\\u043b\\u0438\\u0447\\u0438\\u0442\\u044c \\u043e\\u0442 \\u0432\\u0430\\u0448\\u0438\\u0445 \\u043f\\u0440\\u0438\\u0440\\u043e\\u0434\\u043d\\u044b\\u0445 \\u0432\\u043e\\u043b\\u043e\\u0441.\"},\"image\":\"https:\\/\\/gravity-clinic.com\\/storage\\/uploads\\/1776158523_natural-female-hairline-design-aesthetic.jpg\",\"media_id\":138}]', 'hair', 1, 1, '2026-04-05 20:03:24', '2026-04-14 09:22:04'),
(5, 'beard-moustache-transplant', '{\"en\":\"Beard & Moustache Transplant\",\"ar\":\"\\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0644\\u062d\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0634\\u0627\\u0631\\u0628\",\"fr\":\"Greffe de Barbe et Moustache\",\"ru\":\"\\u041f\\u0435\\u0440\\u0435\\u0441\\u0430\\u0434\\u043a\\u0430 \\u0431\\u043e\\u0440\\u043e\\u0434\\u044b \\u0438 \\u0443\\u0441\\u043e\\u0432\"}', '{\"en\":\"Beard & Moustache Transplant\",\"ar\":\"\\u0632\\u0631\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0644\\u062d\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0634\\u0627\\u0631\\u0628\",\"fr\":\"Greffe Barbe\",\"ru\":\"\\u0411\\u043e\\u0440\\u043e\\u0434\\u0430\"}', 67, 69, 68, '{\"en\":\"Achieve the dense and harmonious beard you\'ve always dreamed of with the latest facial hair transplant techniques in Istanbul. Personalized beard line design that accurately highlights your masculine features with natural precision.\",\"ar\":\"\\u0627\\u062d\\u0635\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0644\\u062d\\u064a\\u0629 \\u0627\\u0644\\u0643\\u062b\\u064a\\u0641\\u0629 \\u0648\\u0627\\u0644\\u0645\\u062a\\u0646\\u0627\\u0633\\u0642\\u0629 \\u0627\\u0644\\u062a\\u064a \\u0637\\u0627\\u0644\\u0645\\u0627 \\u062d\\u0644\\u0645\\u062a \\u0628\\u0647\\u0627 \\u0645\\u0639 \\u0623\\u062d\\u062f\\u062b \\u062a\\u0642\\u0646\\u064a\\u0627\\u062a \\u0632\\u0631\\u0627\\u0639\\u0629 \\u0634\\u0639\\u0631 \\u0627\\u0644\\u0648\\u062c\\u0647 \\u0641\\u064a \\u0625\\u0633\\u0637\\u0646\\u0628\\u0648\\u0644. \\u062a\\u0635\\u0645\\u064a\\u0645 \\u0645\\u062e\\u0635\\u0635 \\u0644\\u062e\\u0637 \\u0627\\u0644\\u0644\\u062d\\u064a\\u0629 \\u064a\\u0628\\u0631\\u0632 \\u0645\\u0644\\u0627\\u0645\\u062d\\u0643 \\u0627\\u0644\\u0631\\u062c\\u0648\\u0644\\u064a\\u0629 \\u0628\\u062f\\u0642\\u0629 \\u0637\\u0628\\u064a\\u0639\\u064a\\u0629.\",\"fr\":\"Obtenez la barbe dense et harmonieuse dont vous avez toujours r\\u00eav\\u00e9 gr\\u00e2ce aux derni\\u00e8res techniques de greffe de poils faciaux \\u00e0 Istanbul. Un design personnalis\\u00e9 de la ligne de barbe qui souligne vos traits masculins avec une pr\\u00e9cision naturelle.\",\"ru\":\"\\u041e\\u0431\\u0440\\u0435\\u0442\\u0438\\u0442\\u0435 \\u0433\\u0443\\u0441\\u0442\\u0443\\u044e \\u0438 \\u0430\\u043a\\u043a\\u0443\\u0440\\u0430\\u0442\\u043d\\u0443\\u044e \\u0431\\u043e\\u0440\\u043e\\u0434\\u0443, \\u043e \\u043a\\u043e\\u0442\\u043e\\u0440\\u043e\\u0439 \\u0432\\u044b \\u0432\\u0441\\u0435\\u0433\\u0434\\u0430 \\u043c\\u0435\\u0447\\u0442\\u0430\\u043b\\u0438, \\u0441 \\u043f\\u043e\\u043c\\u043e\\u0449\\u044c\\u044e \\u043d\\u043e\\u0432\\u0435\\u0439\\u0448\\u0438\\u0445 \\u043c\\u0435\\u0442\\u043e\\u0434\\u043e\\u0432 \\u043f\\u0435\\u0440\\u0435\\u0441\\u0430\\u0434\\u043a\\u0438 \\u0432\\u043e\\u043b\\u043e\\u0441 \\u043d\\u0430 \\u043b\\u0438\\u0446\\u0435 \\u0432 \\u0421\\u0442\\u0430\\u043c\\u0431\\u0443\\u043b\\u0435. \\u0418\\u043d\\u0434\\u0438\\u0432\\u0438\\u0434\\u0443\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u043b\\u0438\\u043d\\u0438\\u0438 \\u0431\\u043e\\u0440\\u043e\\u0434\\u044b, \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0439 \\u043f\\u043e\\u0434\\u0447\\u0435\\u0440\\u043a\\u043d\\u0435\\u0442 \\u0432\\u0430\\u0448\\u0443 \\u043c\\u0443\\u0436\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c \\u0441 \\u0435\\u0441\\u0442\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e\\u0439 \\u0442\\u043e\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c\\u044e.\"}', 99.00, '{\"en\":\"1 Day\",\"ar\":\"\\u064a\\u0648\\u0645 \\u0648\\u0627\\u062d\\u062f\",\"fr\":\"1 Jour\",\"ru\":\"1 \\u0434\\u0435\\u043d\\u044c\"}', '{\"en\":[\"DHI Technique for Extreme Precision Graft Placement\",\"Completely Natural Beard Line Design & Shaping\",\"Strategic Graft Angle & Direction Mapping for Natural Growth\",\"Quick Recovery Time with No Visible Scarring\",\"Permanent Results with Professional Gap Filling\"],\"